export default [
  {"id": "css-01-1", "lang": "css", "level": 1, "title": "Mətn rəngi və fon rəngi", "keywords": ["color", "background-color", "rəng", "fon", "mətn rəngi", "цвет текста", "цвет фона", "renk", "arxa plan", "css əsasları", "ilk css"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Mətn rəngi və fon rəngi</title>\n  <style>\n    body {\n      background-color: #0b1b33;   /* səhifənin fonu */\n      color: #e8f1ff;              /* mətnin rəngi */\n      font-family: sans-serif;\n      padding: 24px;\n    }\n    h1 { color: #2dd4bf; }\n    .vurgu {\n      background-color: #fde68a;\n      color: #1f2937;\n      padding: 8px;\n    }\n  </style>\n</head>\n<body>\n  <h1>Salam, CSS!</h1>\n  <p>Bu paraqrafın rəngi dəyişdirilib.</p>\n  <p class=\"vurgu\">Bu paraqraf vurğulanıb.</p>\n</body>\n</html>\n"},
  {"id": "css-01-2", "lang": "css", "level": 1, "title": "CSS-i HTML-ə üç yolla bağlamaq", "keywords": ["inline style", "style teqi", "external css", "css bağla", "css necə yazılır", "css connect", "внутренний стиль", "inline css", "css yazma yolları"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>CSS-i HTML-ə üç yolla bağlamaq</title>\n  <style>\n    p { color: seagreen; font-size: 18px; }\n    .mavi { color: royalblue; font-weight: bold; }\n  </style>\n</head>\n<body>\n  <h1 style=\"color: tomato;\">1. Inline stil</h1>\n  <p>2. Bu paraqraf &lt;style&gt; blokundakı qaydadan rəng alır.</p>\n  <p class=\"mavi\">3. Class ilə seçilən paraqraf.</p>\n  <!-- 4-cü yol: ayrı style.css faylı və link etiketi (burada fayl yoxdur) -->\n</body>\n</html>\n"},
  {"id": "css-01-3", "lang": "css", "level": 1, "title": "Şrift ölçüsü və qalınlığı", "keywords": ["font-size", "font-weight", "font-style", "şrift ölçüsü", "qalın", "kursiv", "размер шрифта", "жирный", "yazı ölçüsü", "px em rem"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Şrift ölçüsü və qalınlığı</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 20px; }\n    .s1 { font-size: 12px; }\n    .s2 { font-size: 20px; }\n    .s3 { font-size: 2em; }\n    .s4 { font-size: 1.5rem; font-weight: 700; }\n    .s5 { font-style: italic; font-weight: 300; }\n  </style>\n</head>\n<body>\n  <p class=\"s1\">font-size: 12px</p>\n  <p class=\"s2\">font-size: 20px</p>\n  <p class=\"s3\">font-size: 2em</p>\n  <p class=\"s4\">font-size: 1.5rem; qalın</p>\n  <p class=\"s5\">Kursiv və incə</p>\n</body>\n</html>\n"},
  {"id": "css-01-4", "lang": "css", "level": 1, "title": "Mətni hizalamaq və bəzəmək", "keywords": ["text-align", "text-decoration", "text-transform", "hizalama", "altından xətt", "выравнивание текста", "подчеркивание", "ortala", "mətn bəzəyi"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Mətni hizalamaq və bəzəmək</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 20px; }\n    .orta { text-align: center; }\n    .sag { text-align: right; }\n    .alt { text-decoration: underline; }\n    .ust { text-decoration: overline; text-transform: uppercase; }\n    .xett { text-decoration: line-through; color: gray; }\n    a { text-decoration: none; color: teal; }\n  </style>\n</head>\n<body>\n  <h1 class=\"orta\">Ortalanmış başlıq</h1>\n  <p class=\"sag\">Sağa hizalanmış mətn</p>\n  <p class=\"alt\">Altından xətt</p>\n  <p class=\"ust\">üst xətt və böyük hərf</p>\n  <p class=\"xett\">Üstündən xətt çəkilmiş</p>\n  <a href=\"#\">Xəttsiz keçid</a>\n</body>\n</html>\n"},
  {"id": "css-01-5", "lang": "css", "level": 1, "title": "Rəng yazılışları: ad, HEX, RGB, HSL", "keywords": ["rəng formatları", "hex", "rgb", "hsl", "rgba", "color formats", "цветовые форматы", "rəng kodları", "rəng adı", "color picker"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Rəng yazılışları: ad, HEX, RGB, HSL</title>\n  <style>\n    body { font-family: monospace; padding: 16px; }\n    .k { padding: 14px; margin: 8px 0; color: white; border-radius: 6px; text-shadow: 0 1px 2px #0008; }\n    .ad { background: red; }\n    .hex { background: #2dd4bf; }\n    .rgb { background: rgb(59, 130, 246); }\n    .rgba { background: rgba(239, 68, 68, 0.5); color: #333; }\n    .hsl { background: hsl(280, 70%, 55%); }\n  </style>\n</head>\n<body>\n  <div class=\"k ad\">red</div>\n  <div class=\"k hex\">#2dd4bf</div>\n  <div class=\"k rgb\">rgb(59, 130, 246)</div>\n  <div class=\"k rgba\">rgba(239, 68, 68, 0.5)</div>\n  <div class=\"k hsl\">hsl(280, 70%, 55%)</div>\n</body>\n</html>\n"},
  {"id": "css-02-1", "lang": "css", "level": 2, "title": "font-family və ehtiyat şriftlər", "keywords": ["font-family", "şrift ailəsi", "serif", "sans-serif", "monospace", "шрифты", "yazı tipi", "system-ui", "ehtiyat şrift", "font stack"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>font-family və ehtiyat şriftlər</title>\n  <style>\n    body { padding: 20px; font-size: 20px; }\n    .a { font-family: Arial, Helvetica, sans-serif; }\n    .b { font-family: Georgia, \"Times New Roman\", serif; }\n    .c { font-family: \"Courier New\", monospace; }\n    .d { font-family: system-ui, -apple-system, \"Segoe UI\", sans-serif; }\n  </style>\n</head>\n<body>\n  <p class=\"a\">Sans-serif şrift: Salam, dünya!</p>\n  <p class=\"b\">Serif şrift: Salam, dünya!</p>\n  <p class=\"c\">Monospace şrift: Salam, dünya!</p>\n  <p class=\"d\">System UI şrift: Salam, dünya!</p>\n</body>\n</html>\n"},
  {"id": "css-02-2", "lang": "css", "level": 2, "title": "Sətir hündürlüyü və hərf aralığı", "keywords": ["line-height", "letter-spacing", "word-spacing", "sətir aralığı", "hərf aralığı", "межстрочный интервал", "oxunaqlı mətn", "typography", "mətn sıxlığı"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Sətir hündürlüyü və hərf aralığı</title>\n  <style>\n    body { font-family: Arial, sans-serif; max-width: 460px; margin: 20px auto; }\n    .six { line-height: 1; }\n    .rahat { line-height: 1.7; }\n    .aralik { letter-spacing: 6px; word-spacing: 14px; font-weight: bold; text-transform: uppercase; }\n  </style>\n</head>\n<body>\n  <p class=\"six\">Sıx mətn. Sətir aralığı kiçikdir və oxumaq çətinləşir. Sətir aralığı kiçikdir və oxumaq çətinləşir.</p>\n  <p class=\"rahat\">Rahat mətn. Sətir aralığı 1.7 olduqda mətni oxumaq xeyli asan olur. Sətir aralığı 1.7 olduqda mətni oxumaq xeyli asan olur.</p>\n  <p class=\"aralik\">Aralıqlı başlıq</p>\n</body>\n</html>\n"},
  {"id": "css-02-3", "lang": "css", "level": 2, "title": "text-shadow və böyük hərflər", "keywords": ["text-shadow", "kölgə", "mətn kölgəsi", "text-transform", "capitalize", "тень текста", "neon yazı", "parlayan yazı", "glow"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>text-shadow və böyük hərflər</title>\n  <style>\n    body { background: #0a0f1f; color: white; font-family: Arial, sans-serif; text-align: center; padding: 30px; }\n    .neon { color: #5eead4; text-shadow: 0 0 6px #5eead4, 0 0 18px #14b8a6, 0 0 36px #0d9488; }\n    .kolge { text-shadow: 3px 3px 0 #1d4ed8, 6px 6px 0 #0f172a; }\n    .cap { text-transform: capitalize; font-size: 20px; }\n  </style>\n</head>\n<body>\n  <h1 class=\"neon\">NEON YAZI</h1>\n  <h2 class=\"kolge\">Mətn kölgəsi</h2>\n  <p class=\"cap\">hər sözün ilk hərfi böyük olsun</p>\n</body>\n</html>\n"},
  {"id": "css-02-4", "lang": "css", "level": 2, "title": "Siyahı stilləri", "keywords": ["list-style", "siyahı", "ul ol", "маркеры списка", "nişan", "siyahı nişanı", "list-style-type", "nömrələmə", "ul stilləri"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Siyahı stilləri</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 20px; }\n    .a { list-style-type: circle; }\n    .b { list-style-type: square; color: #0f766e; }\n    .c { list-style-type: upper-roman; }\n    .d { list-style: none; padding: 0; }\n    .d li { padding: 6px 0; border-bottom: 1px solid #ddd; }\n  </style>\n</head>\n<body>\n  <ul class=\"a\"><li>Alma</li><li>Armud</li><li>Nar</li></ul>\n  <ul class=\"b\"><li>Kvadrat nişan</li><li>Digər element</li></ul>\n  <ol class=\"c\"><li>Birinci</li><li>İkinci</li><li>Üçüncü</li></ol>\n  <ul class=\"d\"><li>Nişansız</li><li>Siyahı</li></ul>\n</body>\n</html>\n"},
  {"id": "css-02-5", "lang": "css", "level": 2, "title": "Keçid hallarının rəngləri", "keywords": ["a:link", "a:visited", "a:hover", "a:active", "keçid stili", "link rəngi", "ссылки", "hover keçid", "link effekti", "link stilləri"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Keçid hallarının rəngləri</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 24px; font-size: 18px; }\n    a { color: #0f766e; text-decoration: none; border-bottom: 2px solid transparent; transition: border-color .2s; }\n    a:hover { border-bottom-color: #0f766e; }\n    a:active { color: #dc2626; }\n    .duyme { display: inline-block; padding: 10px 18px; background: #0f766e; color: white; border-radius: 8px; border: 0; }\n    .duyme:hover { background: #115e59; }\n  </style>\n</head>\n<body>\n  <p>Keçidlər: <a href=\"#bir\">Bir</a> | <a href=\"#iki\">İki</a> | <a href=\"#uc\">Üç</a></p>\n  <p><a class=\"duyme\" href=\"#duyme\">Düymə kimi keçid</a></p>\n</body>\n</html>\n"},
  {"id": "css-03-1", "lang": "css", "level": 3, "title": "margin və padding", "keywords": ["margin", "padding", "boşluq", "xarici boşluq", "daxili boşluq", "отступы", "kənar boşluğu", "box spacing", "dolgu"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>margin və padding</title>\n  <style>\n    body { font-family: Arial, sans-serif; background: #f1f5f9; padding: 20px; }\n    .qutu { background: #2dd4bf; padding: 24px; margin: 0 0 20px 0; border-radius: 6px; }\n    .ikinci { margin-top: 40px; background: #60a5fa; }\n    .ucuncu { padding: 10px 30px; background: #fbbf24; }\n  </style>\n</head>\n<body>\n  <div class=\"qutu\">Padding: mətnin kənardan məsafəsi</div>\n  <div class=\"qutu ikinci\">Margin: qutular arası məsafə</div>\n  <div class=\"qutu ucuncu\">Qısa yazılış: padding: 10px 30px</div>\n</body>\n</html>\n"},
  {"id": "css-03-2", "lang": "css", "level": 3, "title": "Border stilləri", "keywords": ["border", "çərçivə", "border-style", "solid dashed dotted", "рамка", "kənar xətt", "border-width", "border-color", "border-left"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Border stilləri</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 20px; }\n    .b { padding: 14px; margin: 10px 0; }\n    .solid { border: 3px solid #0f766e; }\n    .dashed { border: 3px dashed #2563eb; }\n    .dotted { border: 4px dotted #dc2626; }\n    .double { border: 6px double #7c3aed; }\n    .sol { border-left: 8px solid #f59e0b; background: #fffbeb; }\n  </style>\n</head>\n<body>\n  <div class=\"b solid\">solid</div>\n  <div class=\"b dashed\">dashed</div>\n  <div class=\"b dotted\">dotted</div>\n  <div class=\"b double\">double</div>\n  <div class=\"b sol\">Yalnız sol xətt</div>\n</body>\n</html>\n"},
  {"id": "css-03-3", "lang": "css", "level": 3, "title": "width, height və box-sizing", "keywords": ["width", "height", "box-sizing", "border-box", "ölçü", "en hündürlük", "ширина", "высота", "qutu ölçüsü", "content-box"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>width, height və box-sizing</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 20px; }\n    div { width: 200px; height: 80px; padding: 20px; border: 5px solid #0f766e; margin-bottom: 16px; background: #ccfbf1; }\n    .a { box-sizing: content-box; }   /* real eni 250px */\n    .b { box-sizing: border-box; }    /* real eni 200px */\n  </style>\n</head>\n<body>\n  <div class=\"a\">content-box: 200px + padding + border</div>\n  <div class=\"b\">border-box: 200px hamısı daxil</div>\n</body>\n</html>\n"},
  {"id": "css-03-4", "lang": "css", "level": 3, "title": "border-radius ilə yumru künclər", "keywords": ["border-radius", "yumru künc", "dairə", "ellips", "скругление углов", "round corners", "pill düymə", "dairəvi qutu", "künc"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>border-radius ilə yumru künclər</title>\n  <style>\n    body { font-family: Arial, sans-serif; display: flex; gap: 16px; flex-wrap: wrap; padding: 20px; background: #0b1b33; }\n    .k { width: 120px; height: 120px; background: #2dd4bf; display: grid; place-items: center; color: #042f2e; font-weight: bold; text-align: center; }\n    .yumru { border-radius: 8px; }\n    .hap { border-radius: 60px / 30px; }\n    .daire { border-radius: 50%; }\n    .yarim { border-radius: 0 60px 0 60px; }\n  </style>\n</head>\n<body>\n  <div class=\"k yumru\">8px</div>\n  <div class=\"k hap\">Həb forması</div>\n  <div class=\"k daire\">Dairə</div>\n  <div class=\"k yarim\">Bir künc</div>\n</body>\n</html>\n"},
  {"id": "css-03-5", "lang": "css", "level": 3, "title": "overflow, max-width və text-overflow", "keywords": ["overflow", "max-width", "scroll", "hidden", "text-overflow ellipsis", "переполнение", "kəsilmiş mətn", "üç nöqtə", "sürüşdürmə", "uzun mətn"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>overflow, max-width və text-overflow</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 20px; }\n    div { width: 220px; margin-bottom: 16px; padding: 8px; border: 2px solid #0f766e; }\n    .a { height: 60px; overflow: auto; }\n    .b { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n    .c { height: 30px; overflow: hidden; background: #ccfbf1; }\n    .c::after { content: \" ... bu hissə görünmür, çünki hündürlük kəsilib. Bu hissə görünmür.\"; display: block; }\n  </style>\n</head>\n<body>\n  <div class=\"a\">Bu çox uzun mətndir və qutuya sığmır, ona görə scroll zolağı çıxır. Bu çox uzun mətndir və qutuya sığmır.</div>\n  <div class=\"b\">Bu mətn tək sətirdə qalır və sonu üç nöqtə ilə kəsilir, çünki çox uzundur.</div>\n  <div class=\"c\">Gizlənən hissə</div>\n</body>\n</html>\n"},
  {"id": "css-04-1", "lang": "css", "level": 4, "title": "linear-gradient", "keywords": ["linear-gradient", "gradient", "rəng keçidi", "qradiyent", "градиент", "fon gradient", "istiqamət", "deg", "rəng axını", "background gradient"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>linear-gradient</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 20px; background: #0b1b33; }\n    .g { height: 110px; margin-bottom: 14px; border-radius: 12px; color: white; display: grid; place-items: center; font-size: 22px; font-weight: bold; }\n    .g1 { background: linear-gradient(to right, #14b8a6, #2563eb); }\n    .g2 { background: linear-gradient(135deg, #7c3aed, #ec4899); }\n    .g3 { background: linear-gradient(90deg, #ef4444, #f59e0b 30%, #22c55e 60%, #3b82f6); }\n  </style>\n</head>\n<body>\n  <div class=\"g g1\">to right</div>\n  <div class=\"g g2\">135deg</div>\n  <div class=\"g g3\">Çoxrəngli</div>\n</body>\n</html>\n"},
  {"id": "css-04-2", "lang": "css", "level": 4, "title": "radial-gradient və conic-gradient", "keywords": ["radial-gradient", "conic-gradient", "dairəvi gradient", "pie chart", "радиальный градиент", "dairə diaqramı", "qradiyent dairə", "rəng çarxı"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>radial-gradient və conic-gradient</title>\n  <style>\n    body { background: #0b1b33; display: flex; gap: 24px; padding: 30px; flex-wrap: wrap; }\n    .r, .c, .pie { width: 140px; height: 140px; border-radius: 50%; }\n    .r { background: radial-gradient(circle at 30% 30%, #99f6e4, #0d9488 55%, #134e4a); }\n    .c { background: conic-gradient(red, yellow, lime, aqua, blue, magenta, red); }\n    .pie { background: conic-gradient(#14b8a6 0 40%, #3b82f6 0 70%, #f59e0b 0 100%); }\n  </style>\n</head>\n<body>\n  <div class=\"r\"></div>\n  <div class=\"c\"></div>\n  <div class=\"pie\"></div>\n</body>\n</html>\n"},
  {"id": "css-04-3", "lang": "css", "level": 4, "title": "box-shadow", "keywords": ["box-shadow", "kölgə", "qutu kölgəsi", "тень блока", "soft shadow", "inset shadow", "çoxqatlı kölgə", "kart kölgəsi", "elevated"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>box-shadow</title>\n  <style>\n    body { background: #e2e8f0; display: flex; gap: 24px; flex-wrap: wrap; padding: 30px; font-family: Arial, sans-serif; }\n    .k { width: 120px; height: 90px; background: white; border-radius: 12px; display: grid; place-items: center; }\n    .s1 { box-shadow: 0 10px 30px rgba(15, 23, 42, .18); }\n    .s2 { box-shadow: 8px 8px 0 #0f766e; }\n    .s3 { box-shadow: inset 0 4px 12px rgba(0, 0, 0, .3); }\n    .s4 { background: #0f172a; color: #5eead4; box-shadow: 0 0 24px #14b8a6; }\n  </style>\n</head>\n<body>\n  <div class=\"k s1\">Yumşaq</div>\n  <div class=\"k s2\">Sərt</div>\n  <div class=\"k s3\">İçəri</div>\n  <div class=\"k s4\">Rəngli glow</div>\n</body>\n</html>\n"},
  {"id": "css-04-4", "lang": "css", "level": 4, "title": "opacity və şəffaf rənglər", "keywords": ["opacity", "şəffaflıq", "rgba", "прозрачность", "transparency", "yarı şəffaf", "overlay", "örtük", "alpha"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>opacity və şəffaf rənglər</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 20px; }\n    .foto { height: 120px; border-radius: 12px; background: linear-gradient(135deg, #0ea5e9, #6366f1); position: relative; }\n    .yazi { position: absolute; inset: auto 0 0 0; padding: 12px; background: rgba(0, 0, 0, .45); color: white; border-radius: 0 0 12px 12px; }\n    .sira { display: flex; gap: 10px; margin-top: 16px; }\n    .o { width: 70px; height: 70px; background: #0f766e; color: white; display: grid; place-items: center; border-radius: 8px; }\n    .o1 { opacity: 1; } .o2 { opacity: .7; } .o3 { opacity: .4; } .o4 { opacity: .15; }\n  </style>\n</head>\n<body>\n  <div class=\"foto\"><div class=\"yazi\">Üstdə yazı</div></div>\n  <div class=\"sira\">\n    <div class=\"o o1\">1.0</div><div class=\"o o2\">0.7</div><div class=\"o o3\">0.4</div><div class=\"o o4\">0.15</div>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-04-5", "lang": "css", "level": 4, "title": "Gradient ilə naxışlar", "keywords": ["pattern", "naxış", "zolaqlı fon", "xanalı fon", "repeating-linear-gradient", "background-size", "полосатый фон", "checkerboard", "şəkilsiz naxış"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Gradient ilə naxışlar</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 20px; background: #f8fafc; }\n    .n { height: 90px; margin-bottom: 14px; border-radius: 10px; display: grid; place-items: center; font-weight: bold; color: #0f172a; }\n    .zolaq { background: repeating-linear-gradient(45deg, #99f6e4 0 12px, #5eead4 12px 24px); }\n    .xana { background-color: #fff;\n      background-image: linear-gradient(#cbd5e1 1px, transparent 1px), linear-gradient(90deg, #cbd5e1 1px, transparent 1px);\n      background-size: 20px 20px; }\n    .noqte { background-color: #0f172a; color: white; background-image: radial-gradient(#2dd4bf 2px, transparent 2px); background-size: 18px 18px; }\n  </style>\n</head>\n<body>\n  <div class=\"n zolaq\">Zolaqlı</div>\n  <div class=\"n xana\">Xanalı</div>\n  <div class=\"n noqte\">Nöqtəli</div>\n</body>\n</html>\n"},
  {"id": "css-05-1", "lang": "css", "level": 5, "title": "Tag, class və id selektorları", "keywords": ["selector", "selektor", "class", "id", "tag", "seçici", "css selector", "селекторы", "class id fərqi", "nöqtə diyez"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Tag, class və id selektorları</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 20px; }\n    p { color: #334155; }                 /* tag selektoru */\n    .vacib { color: #0f766e; font-weight: bold; }   /* class: nöqtə ilə */\n    #xususi { background: #fef3c7; padding: 8px; }  /* id: diyez ilə */\n    .vacib.kicik { font-size: 14px; }     /* hər iki class olan */\n  </style>\n</head>\n<body>\n  <p>Adi paraqraf</p>\n  <p class=\"vacib\">Class ilə seçilən</p>\n  <p id=\"xususi\">ID ilə seçilən (səhifədə yalnız bir dənə)</p>\n  <p class=\"vacib kicik\">Bir neçə class</p>\n</body>\n</html>\n"},
  {"id": "css-05-2", "lang": "css", "level": 5, "title": "Descendant, child və qonşu selektorlar", "keywords": ["descendant selector", "child selector", ">", "+", "~", "nəslin selektoru", "комбинаторы", "qonşu element", "adjacent", "daxildəki elementlər"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Descendant, child və qonşu selektorlar</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 20px; }\n    .qutu p { color: #64748b; }                          /* bütün nəsil */\n    .qutu > p { border-left: 4px solid #0f766e; padding-left: 8px; } /* yalnız birbaşa uşaq */\n    h3 + p { background: #ccfbf1; }                      /* ilk qonşu */\n    h3 ~ p { font-style: italic; }                       /* sonrakı bütün qardaşlar */\n  </style>\n</head>\n<body>\n  <div class=\"qutu\">\n    <p>Birbaşa uşaq</p>\n    <section><p>Nəvə paraqraf</p></section>\n    <h3>Başlıq</h3>\n    <p>Başlıqdan sonrakı paraqraf</p>\n    <p>Sonrakı paraqraf</p>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-05-3", "lang": "css", "level": 5, "title": "Qruplaşdırma və universal selektor", "keywords": ["qruplaşdırma", "* selektoru", "universal selector", "group selector", "vergül", "reset css", "общий селектор", "margin sıfırla", "bütün elementlər"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Qruplaşdırma və universal selektor</title>\n  <style>\n    * { margin: 0; padding: 0; box-sizing: border-box; }    /* reset */\n    body { font-family: Arial, sans-serif; padding: 24px; display: grid; gap: 12px; justify-items: start; }\n    h1, h2, p { color: #0f766e; }                            /* qrup: vergüllə */\n    h1, h2 { text-transform: uppercase; letter-spacing: 1px; }\n    button { padding: 8px 16px; }\n  </style>\n</head>\n<body>\n  <h1>Başlıq 1</h1>\n  <h2>Başlıq 2</h2>\n  <p>Paraqraf</p>\n  <button>Düymə</button>\n</body>\n</html>\n"},
  {"id": "css-05-4", "lang": "css", "level": 5, "title": ":hover, :focus və :active halları", "keywords": ["hover", "focus", "active", "pseudo-class", "hal", "düymə halları", "интерактивные состояния", "üzərinə gələndə", "klikləndikdə", "focus halı"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>:hover, :focus və :active halları</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 24px; }\n    .d { padding: 12px 22px; border: 0; border-radius: 8px; background: #0f766e; color: white; font-size: 16px; cursor: pointer; }\n    .d:hover { background: #14b8a6; }\n    .d:active { transform: scale(.95); }\n    .i { padding: 10px; border: 2px solid #cbd5e1; border-radius: 8px; outline: none; }\n    .i:focus { border-color: #0f766e; box-shadow: 0 0 0 4px rgba(20, 184, 166, .25); }\n    .k { margin-top: 16px; padding: 24px; background: #e2e8f0; border-radius: 10px; transition: background .2s; }\n    .k:hover { background: #99f6e4; }\n  </style>\n</head>\n<body>\n  <button class=\"d\">Üzərinə gəl və bas</button>\n  <p><input class=\"i\" placeholder=\"Bura kliklə (focus)\"></p>\n  <div class=\"k\">Kartın üzərinə gəl</div>\n</body>\n</html>\n"},
  {"id": "css-05-5", "lang": "css", "level": 5, "title": ":first-child, :last-child və :nth-child", "keywords": ["nth-child", "first-child", "last-child", "zebra cədvəl", "tək cüt sətir", "çoxluq selektor", ":nth-of-type", "чётные нечётные", "növbəli rənglər"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>:first-child, :last-child və :nth-child</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 20px; }\n    ul { list-style: none; padding: 0; width: 220px; border-radius: 10px; overflow: hidden; border: 1px solid #cbd5e1; }\n    li { padding: 10px 14px; }\n    li:nth-child(even) { background: #f1f5f9; }   /* cüt sətirlər */\n    li:nth-child(3n) { color: #0f766e; font-weight: bold; }   /* hər üçüncü */\n    li:first-child { background: #0f766e; color: white; }\n    li:last-child { border-top: 2px dashed #94a3b8; }\n  </style>\n</head>\n<body>\n  <ul>\n    <li>Bir</li><li>İki</li><li>Üç</li><li>Dörd</li><li>Beş</li><li>Altı</li>\n  </ul>\n</body>\n</html>\n"},
  {"id": "css-06-1", "lang": "css", "level": 6, "title": "::before və ::after", "keywords": ["before", "after", "pseudo-element", "content", "::before ::after", "псевдоэлементы", "bəzək", "ikon əvəzi", "işarə əlavə et", "dekorativ"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>::before və ::after</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 24px; }\n    .b::before { content: \"★ \"; color: #f59e0b; }\n    .b::after { content: \"\"; display: block; width: 60px; height: 4px; background: #0f766e; margin-top: 6px; border-radius: 2px; }\n    .l::after { content: \" ↗\"; font-size: .8em; }\n    .q { font-size: 20px; padding-left: 30px; position: relative; color: #475569; }\n    .q::before { content: \"“\"; position: absolute; left: 0; top: -8px; font-size: 48px; color: #14b8a6; }\n  </style>\n</head>\n<body>\n  <h2 class=\"b\">Başlıq</h2>\n  <a class=\"l\" href=\"#\">Xarici keçid</a>\n  <p class=\"q\">Sitat mətni burada yazılır</p>\n</body>\n</html>\n"},
  {"id": "css-06-2", "lang": "css", "level": 6, "title": "::first-letter və ::first-line", "keywords": ["first-letter", "first-line", "drop cap", "ilk hərf", "birinci sətir", "буквица", "jurnal stili", "paraqraf bəzəyi", "ilk hərfi böyüt"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>::first-letter və ::first-line</title>\n  <style>\n    body { font-family: Georgia, serif; max-width: 420px; margin: 30px auto; line-height: 1.6; font-size: 18px; }\n    .mesel::first-letter { float: left; font-size: 3.4em; line-height: .9; padding-right: 8px; color: #0f766e; font-weight: bold; }\n    .mesel::first-line { text-transform: uppercase; letter-spacing: 1px; color: #134e4a; }\n  </style>\n</head>\n<body>\n  <p class=\"mesel\">Əvvəl ölçü, sonra biç. Ağıllı adam sözü sınayıb danışar, nadan isə danışıb sınayar. Bu mətn bir neçə sətrə yayılsın deyə uzun yazılıb ki, ilk sətir fərqi görünsün.</p>\n</body>\n</html>\n"},
  {"id": "css-06-3", "lang": "css", "level": 6, "title": "Atribut selektorları", "keywords": ["attribute selector", "[type=text]", "[href^=]", "[href$=]", "atribut seçici", "селектор атрибута", "input tipinə görə", "fayl tipi ikonu", "a[target]"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Atribut selektorları</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 20px; }\n    input[type=\"text\"], input[type=\"email\"] { padding: 8px; border: 2px solid #94a3b8; border-radius: 6px; }\n    input[type=\"email\"] { border-color: #0f766e; }\n    a { text-decoration: none; color: #1d4ed8; }\n    a[href^=\"https\"]::before { content: \"🔒 \"; }\n    a[href$=\".pdf\"]::before { content: \"📄 \"; }\n    a[href$=\".png\"]::before { content: \"🖼 \"; }\n    a[href^=\"mailto:\"]::before { content: \"✉ \"; }\n  </style>\n</head>\n<body>\n  <p><input type=\"text\" placeholder=\"mətn\"></p>\n  <p><input type=\"email\" placeholder=\"email\"></p>\n  <p><input type=\"checkbox\"> işarələ</p>\n  <ul>\n    <li><a href=\"https://nibrascode.com\">Sayt (https)</a></li>\n    <li><a href=\"sened.pdf\">sened.pdf</a></li>\n    <li><a href=\"foto.png\">foto.png</a></li>\n    <li><a href=\"mailto:nibrascode@gmail.com\">Email</a></li>\n  </ul>\n</body>\n</html>\n"},
  {"id": "css-06-4", "lang": "css", "level": 6, "title": ":not(), :is() və :has()", "keywords": ["not", "is", "has", ":not", ":is", ":has", "мощные селекторы", "valideyn seçici", "şərtli seçim", "parent selector", "modern css"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>:not(), :is() və :has()</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 20px; }\n    .kart { border: 2px solid #cbd5e1; border-radius: 10px; padding: 12px; margin-bottom: 12px; width: 240px; }\n    .kart:has(.sekil) { border-color: #0f766e; background: #f0fdfa; }   /* içində .sekil olan kart */\n    .sekil { height: 50px; background: #14b8a6; border-radius: 6px; }\n    .s li:not(.son) { color: #475569; }\n    .s :is(li, p):last-child { font-weight: bold; }\n    .s li.son { color: #dc2626; }\n  </style>\n</head>\n<body>\n  <div class=\"kart\"><h3>Şəkilli kart</h3><div class=\"sekil\"></div></div>\n  <div class=\"kart\"><h3>Şəkilsiz kart</h3></div>\n  <ul class=\"s\"><li>Bir</li><li class=\"son\">İki (son)</li><li>Üç</li></ul>\n</body>\n</html>\n"},
  {"id": "css-06-5", "lang": "css", "level": 6, "title": "::selection, ::placeholder və marker", "keywords": ["selection", "placeholder", "marker", "::selection", "seçilmiş mətn rəngi", "::marker", "outline", "выделение текста", "placeholder rəngi", "seçim stili"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>::selection, ::placeholder və marker</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 24px; font-size: 18px; }\n    ::selection { background: #0f766e; color: white; }\n    input { padding: 10px; border: 2px solid #cbd5e1; border-radius: 8px; }\n    input::placeholder { color: #0f766e; font-style: italic; }\n    .m li::marker { color: #14b8a6; font-size: 1.3em; }\n  </style>\n</head>\n<body>\n  <p>Bu mətni siçanla seçin: rəng dəyişir.</p>\n  <input placeholder=\"Bu placeholder-dir\">\n  <ul class=\"m\"><li>Marker rəngli</li><li>Siyahı elementi</li></ul>\n</body>\n</html>\n"},
  {"id": "css-07-1", "lang": "css", "level": 7, "title": "display: block, inline, inline-block", "keywords": ["display", "block", "inline", "inline-block", "none", "блочные элементы", "görünüş növü", "xətti element", "gizlət", "display none"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>display: block, inline, inline-block</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 20px; }\n    span { background: #99f6e4; margin: 4px; }\n    .in { display: inline; padding: 20px; }          /* hündürlük/en işləmir */\n    .ib { display: inline-block; width: 120px; height: 40px; text-align: center; line-height: 40px; }\n    .bl { display: block; width: 160px; padding: 8px; }\n    .gizli { display: none; }\n  </style>\n</head>\n<body>\n  <span class=\"in\">inline</span><span class=\"in\">inline</span>\n  <span class=\"ib\">inline-block</span><span class=\"ib\">inline-block</span>\n  <span class=\"bl\">block</span><span class=\"bl\">block</span>\n  <div class=\"gizli\">Bu görünmür</div>\n  <p>Gizli element səhifədə yer tutmur.</p>\n</body>\n</html>\n"},
  {"id": "css-07-2", "lang": "css", "level": 7, "title": "position: relative və absolute", "keywords": ["position", "relative", "absolute", "top left", "mövqe", "yerləşdirmə", "позиционирование", "bildiriş nişanı", "badge", "üst-üstə qoy"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>position: relative və absolute</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 40px; }\n    .valideyn { position: relative; width: 220px; }\n    .kart { padding: 30px 20px; background: #e2e8f0; border-radius: 12px; }\n    .nisan { position: absolute; top: -10px; right: -10px; width: 26px; height: 26px; border-radius: 50%; background: #dc2626; color: white; font-size: 14px; display: grid; place-items: center; z-index: 1; }\n    .sol-ust { position: relative; top: 20px; left: 30px; background: #fef3c7; padding: 10px; width: 160px; }\n  </style>\n</head>\n<body>\n  <div class=\"valideyn\">\n    <span class=\"nisan\">3</span>\n    <div class=\"kart\">Valideyn qutu (relative)</div>\n  </div>\n  <div class=\"sol-ust\">Sol yuxarı küncdə</div>\n</body>\n</html>\n"},
  {"id": "css-07-3", "lang": "css", "level": 7, "title": "position: fixed və sticky", "keywords": ["fixed", "sticky", "yapışqan başlıq", "sabit düymə", "back to top", "прилипающий элемент", "scroll zamanı sabit", "floating button", "sticky header"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>position: fixed və sticky</title>\n  <style>\n    body { font-family: Arial, sans-serif; margin: 0; }\n    .bas { position: sticky; top: 0; background: #0f766e; color: white; padding: 14px 20px; font-weight: bold; }\n    main { padding: 20px; }\n    main p { margin: 0 0 60px; }\n    .yuxari { position: fixed; right: 16px; bottom: 16px; padding: 10px 14px; border: 0; border-radius: 999px; background: #0b1b33; color: #5eead4; cursor: pointer; }\n  </style>\n</head>\n<body>\n  <header class=\"bas\">Yapışqan başlıq (sticky)</header>\n  <main>\n    <p>Aşağı sürüşdürün...</p>\n    <p>Mətn 1</p><p>Mətn 2</p><p>Mətn 3</p><p>Mətn 4</p><p>Mətn 5</p><p>Mətn 6</p>\n    <p>Mətn 7</p><p>Mətn 8</p><p>Mətn 9</p><p>Mətn 10</p><p>Mətn 11</p><p>Mətn 12</p>\n  </main>\n  <button class=\"yuxari\">↑ Yuxarı</button>\n</body>\n</html>\n"},
  {"id": "css-07-4", "lang": "css", "level": 7, "title": "z-index və qatlar", "keywords": ["z-index", "qat", "üst-üstə düşmə", "layers", "стекинг", "overlap", "öndə arxada", "stacking context", "hansı üstdədir"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>z-index və qatlar</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 30px; }\n    .qat { position: absolute; width: 150px; height: 110px; padding: 10px; color: white; border-radius: 10px; font-weight: bold; }\n    .a { left: 40px; top: 40px; background: #0f766e; z-index: 1; }\n    .b { left: 100px; top: 80px; background: #2563eb; z-index: 3; }\n    .c { left: 160px; top: 40px; background: #db2777; z-index: 2; }\n  </style>\n</head>\n<body>\n  <div class=\"qat a\">A (z-index: 1)</div>\n  <div class=\"qat b\">B (z-index: 3)</div>\n  <div class=\"qat c\">C (z-index: 2)</div>\n</body>\n</html>\n"},
  {"id": "css-07-5", "lang": "css", "level": 7, "title": "float ilə mətn axını", "keywords": ["float", "clear", "mətn ətrafı", "sola yapış", "обтекание", "text wrap", "clearfix", "şəkil və mətn", "float left"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>float ilə mətn axını</title>\n  <style>\n    body { font-family: Arial, sans-serif; max-width: 420px; margin: 20px auto; line-height: 1.6; }\n    .blok { float: left; width: 110px; height: 110px; margin: 4px 14px 8px 0; background: #14b8a6; border-radius: 12px; }\n    .temiz { clear: both; }\n  </style>\n</head>\n<body>\n  <div class=\"blok\"></div>\n  <p>Rəngli qutu solda üzür (float: left), bu mətn isə onun ətrafından axır. Mətn uzandıqca qutunun altından tam eninə qayıdır. Bu üsulla jurnal səhifələrinin görünüşünü almaq olar. Əvvəllər float səhifə düzülüşü üçün istifadə olunurdu, indi flex və grid daha yaxşı seçimdir.</p>\n  <div class=\"temiz\"></div>\n  <p>Float-dan sonra clear: both ilə normal axına qayıdırıq.</p>\n</body>\n</html>\n"},
  {"id": "css-08-1", "lang": "css", "level": 8, "title": "Flexbox: display flex və direction", "keywords": ["flex", "flexbox", "flex-direction", "row column", "sıra və sütun", "flex konteyner", "гибкий контейнер", "flex əsasları", "display flex"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Flexbox: display flex və direction</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 20px; }\n    .sira, .sutun { display: flex; gap: 10px; margin-bottom: 20px; padding: 10px; background: #e2e8f0; border-radius: 10px; }\n    .sutun { flex-direction: column; width: 120px; }\n    .tersi { flex-direction: row-reverse; }\n    .sira div, .sutun div { background: #0f766e; color: white; padding: 14px 20px; border-radius: 8px; font-weight: bold; }\n  </style>\n</head>\n<body>\n  <div class=\"sira\"><div>1</div><div>2</div><div>3</div></div>\n  <div class=\"sutun\"><div>A</div><div>B</div><div>C</div></div>\n  <div class=\"sira tersi\"><div>1</div><div>2</div><div>3</div></div>\n</body>\n</html>\n"},
  {"id": "css-08-2", "lang": "css", "level": 8, "title": "justify-content", "keywords": ["justify-content", "flex-start", "center", "space-between", "space-around", "space-evenly", "hizalama", "əsas ox", "выравнивание flex", "flex yerləşdirmə"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>justify-content</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 16px; font-size: 14px; }\n    p { margin: 8px 0 2px; color: #475569; }\n    .f { display: flex; background: #e2e8f0; padding: 6px; border-radius: 8px; }\n    .f i { font-style: normal; background: #0f766e; color: white; width: 44px; height: 36px; display: grid; place-items: center; border-radius: 6px; }\n    .a { justify-content: flex-start; } .b { justify-content: center; } .c { justify-content: space-between; }\n    .d { justify-content: space-around; } .e { justify-content: space-evenly; }\n  </style>\n</head>\n<body>\n  <p>flex-start</p><div class=\"f a\"><i>1</i><i>2</i><i>3</i></div>\n  <p>center</p><div class=\"f b\"><i>1</i><i>2</i><i>3</i></div>\n  <p>space-between</p><div class=\"f c\"><i>1</i><i>2</i><i>3</i></div>\n  <p>space-around</p><div class=\"f d\"><i>1</i><i>2</i><i>3</i></div>\n  <p>space-evenly</p><div class=\"f e\"><i>1</i><i>2</i><i>3</i></div>\n</body>\n</html>\n"},
  {"id": "css-08-3", "lang": "css", "level": 8, "title": "align-items və align-self", "keywords": ["align-items", "align-self", "çarpaz ox", "şaquli hizalama", "вертикальное выравнивание", "center vertical", "flex-end", "stretch", "baseline"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>align-items və align-self</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 16px; }\n    .f { display: flex; gap: 8px; height: 90px; background: #e2e8f0; padding: 6px; border-radius: 8px; margin-bottom: 10px; }\n    .f i { font-style: normal; background: #0f766e; color: white; padding: 6px 14px; border-radius: 6px; }\n    .a { align-items: stretch; } .b { align-items: center; } .c { align-items: flex-end; }\n    .d { align-items: flex-start; }\n    .ozu { align-self: flex-end; background: #db2777 !important; }\n  </style>\n</head>\n<body>\n  <div class=\"f a\"><i>stretch</i><i>1</i></div>\n  <div class=\"f b\"><i>center</i><i>1</i></div>\n  <div class=\"f c\"><i>end</i><i>1</i></div>\n  <div class=\"f d\"><i>1</i><i class=\"ozu\">align-self</i><i>3</i></div>\n</body>\n</html>\n"},
  {"id": "css-08-4", "lang": "css", "level": 8, "title": "flex-wrap və gap", "keywords": ["flex-wrap", "gap", "sətrə keç", "çox element", "обернуть", "wrap", "boşluq", "row-gap", "etiketlər", "tag cloud"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>flex-wrap və gap</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 20px; }\n    .etiketler { display: flex; flex-wrap: wrap; gap: 10px 8px; max-width: 360px; }\n    .etiketler span { background: #ccfbf1; color: #115e59; padding: 6px 14px; border-radius: 999px; font-size: 14px; border: 1px solid #5eead4; }\n  </style>\n</head>\n<body>\n  <div class=\"etiketler\">\n    <span>HTML</span><span>CSS</span><span>JavaScript</span><span>Python</span><span>SQL</span>\n    <span>Git</span><span>Flexbox</span><span>Grid</span><span>React</span><span>Node.js</span>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-08-5", "lang": "css", "level": 8, "title": "flex-grow, flex-shrink və flex-basis", "keywords": ["flex-grow", "flex-shrink", "flex-basis", "flex: 1", "bərabər bölüş", "qalan yeri doldur", "растягивание", "proporsional", "nisbət"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>flex-grow, flex-shrink və flex-basis</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 20px; }\n    .s { display: flex; gap: 10px; margin-bottom: 16px; }\n    .s div { padding: 18px; color: white; border-radius: 8px; text-align: center; }\n    .a, .c { flex: 1; background: #0f766e; }\n    .b { flex: 2; background: #2563eb; }\n    .sabit { flex: 0 0 100px; background: #7c3aed; }\n    .doldur { flex: 1; background: #db2777; }\n  </style>\n</head>\n<body>\n  <div class=\"s\">\n    <div class=\"a\">flex: 1</div>\n    <div class=\"b\">flex: 2</div>\n    <div class=\"c\">flex: 1</div>\n  </div>\n  <div class=\"s\">\n    <div class=\"sabit\">sabit 100px</div>\n    <div class=\"doldur\">qalan yeri doldurur</div>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-09-1", "lang": "css", "level": 9, "title": "Elementi mərkəzləmək", "keywords": ["mərkəzləmək", "center", "ortala", "vertical center", "horizontal center", "центрирование", "tam ortada", "place-items", "div ortalamaq"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Elementi mərkəzləmək</title>\n  <style>\n    body { margin: 0; font-family: Arial, sans-serif; }\n    .sehne { height: 100vh; display: grid; place-items: center; background: #0b1b33; }\n    /* Eyni nəticə flex ilə: display: flex; justify-content: center; align-items: center; */\n    .qutu { padding: 30px 50px; background: #14b8a6; color: #042f2e; font-size: 22px; font-weight: bold; border-radius: 14px; }\n  </style>\n</head>\n<body>\n  <div class=\"sehne\">\n    <div class=\"qutu\">Tam mərkəzdə</div>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-09-2", "lang": "css", "level": 9, "title": "Flex ilə naviqasiya paneli", "keywords": ["navbar", "naviqasiya", "menyu", "nav bar", "меню навигации", "üst menyu", "logo və linklər", "header", "sayt başlığı"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Flex ilə naviqasiya paneli</title>\n  <style>\n    body { margin: 0; font-family: Arial, sans-serif; background: #f1f5f9; }\n    .nav { display: flex; align-items: center; gap: 24px; padding: 14px 24px; background: #0b1b33; color: white; }\n    .logo { font-weight: bold; font-size: 20px; color: #5eead4; margin-right: auto; }\n    .nav ul { display: flex; gap: 20px; list-style: none; margin: 0; padding: 0; }\n    .nav a { color: #e2e8f0; text-decoration: none; }\n    .nav li a:hover { color: #5eead4; }\n    .duyme { background: #14b8a6; color: #042f2e !important; padding: 8px 16px; border-radius: 8px; font-weight: bold; }\n  </style>\n</head>\n<body>\n  <nav class=\"nav\">\n    <div class=\"logo\">Nibras</div>\n    <ul>\n      <li><a href=\"#\">Ana səhifə</a></li>\n      <li><a href=\"#\">Tətbiqlər</a></li>\n      <li><a href=\"#\">Haqqında</a></li>\n    </ul>\n    <a class=\"duyme\" href=\"#\">Əlaqə</a>\n  </nav>\n</body>\n</html>\n"},
  {"id": "css-09-3", "lang": "css", "level": 9, "title": "Kartlar sırası (flex)", "keywords": ["kartlar", "cards", "kart sırası", "card layout", "карточки", "flex kartlar", "məhsul kartları", "bərabər hündürlük", "üç kart"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Kartlar sırası (flex)</title>\n  <style>\n    body { font-family: Arial, sans-serif; background: #f1f5f9; padding: 24px; }\n    .sira { display: flex; gap: 16px; flex-wrap: wrap; }\n    .kart { flex: 1 1 200px; display: flex; flex-direction: column; background: white; padding: 18px; border-radius: 14px; box-shadow: 0 6px 18px rgba(15, 23, 42, .1); }\n    .kart h3 { margin: 0 0 8px; color: #0f766e; }\n    .kart p { color: #475569; flex: 1; margin: 0 0 14px; }\n    .kart a { color: #0f766e; font-weight: bold; text-decoration: none; }\n  </style>\n</head>\n<body>\n  <div class=\"sira\">\n    <article class=\"kart\"><h3>Nibras Arabic</h3><p>Ərəb dilini asan öyrən.</p><a href=\"#\">Ətraflı</a></article>\n    <article class=\"kart\"><h3>Nibras PDF</h3><p>PDF fayllarla rahat işlə.</p><a href=\"#\">Ətraflı</a></article>\n    <article class=\"kart\"><h3>Nibras Plans</h3><p>Planlarını bir yerdə saxla. Bu kartın mətni daha uzundur və hündürlük bərabər qalır.</p><a href=\"#\">Ətraflı</a></article>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-09-4", "lang": "css", "level": 9, "title": "Footer həmişə aşağıda (sticky footer)", "keywords": ["sticky footer", "footer aşağıda", "səhifə sonu", "футер внизу", "min-height 100vh", "qısa səhifə footer", "flex column layout"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Footer həmişə aşağıda (sticky footer)</title>\n  <style>\n    body { margin: 0; min-height: 100vh; display: flex; flex-direction: column; font-family: Arial, sans-serif; }\n    header { background: #0b1b33; color: #5eead4; padding: 16px 24px; font-weight: bold; }\n    main { flex: 1; padding: 24px; background: #f8fafc; }   /* qalan bütün yeri tutur */\n    footer { background: #0b1b33; color: #94a3b8; padding: 14px 24px; text-align: center; font-size: 14px; }\n  </style>\n</head>\n<body>\n  <header>Başlıq</header>\n  <main>Qısa məzmun. Footer yenə də səhifənin ən altında qalır.</main>\n  <footer>© 2026 Nibras Code</footer>\n</body>\n</html>\n"},
  {"id": "css-09-5", "lang": "css", "level": 9, "title": "Holy Grail düzülüşü (flex)", "keywords": ["holy grail", "üç sütunlu layout", "sidebar", "əsas hissə", "макет", "header sidebar content footer", "sayt skeleti", "layout"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Holy Grail düzülüşü (flex)</title>\n  <style>\n    * { box-sizing: border-box; }\n    body { margin: 0; font-family: Arial, sans-serif; }\n    .sehife { min-height: 100vh; display: flex; flex-direction: column; }\n    header, footer { background: #0b1b33; color: white; padding: 16px; }\n    .orta { flex: 1; display: flex; }\n    nav { flex: 0 0 150px; background: #ccfbf1; padding: 16px; }\n    main { flex: 1; padding: 16px; background: #f8fafc; }\n    aside { flex: 0 0 150px; background: #e0f2fe; padding: 16px; }\n    @media (max-width: 560px) { .orta { flex-direction: column; } nav, aside { flex-basis: auto; } }\n  </style>\n</head>\n<body>\n  <div class=\"sehife\">\n    <header>Header</header>\n    <div class=\"orta\">\n      <nav>Menyu</nav>\n      <main>Əsas məzmun burada olur. Mobil ekranda sütunlar alt-alta düzülür.</main>\n      <aside>Yan hissə</aside>\n    </div>\n    <footer>Footer</footer>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-10-1", "lang": "css", "level": 10, "title": "Grid: sütunlar və sətirlər", "keywords": ["grid", "css grid", "grid-template-columns", "grid-template-rows", "şəbəkə", "сетка", "grid əsasları", "grid konteyner", "3 sütun"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Grid: sütunlar və sətirlər</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 20px; }\n    .grid {\n      display: grid;\n      grid-template-columns: 100px 150px 100px;\n      grid-template-rows: 70px 70px;\n      gap: 10px;\n    }\n    .grid div { background: #0f766e; color: white; display: grid; place-items: center; border-radius: 8px; font-size: 20px; }\n  </style>\n</head>\n<body>\n  <div class=\"grid\">\n    <div>1</div><div>2</div><div>3</div>\n    <div>4</div><div>5</div><div>6</div>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-10-2", "lang": "css", "level": 10, "title": "fr, repeat və gap", "keywords": ["fr vahidi", "repeat", "grid gap", "bərabər sütun", "1fr 2fr", "равные колонки", "sütun bölgüsü", "grid nisbət", "minmax"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>fr, repeat və gap</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 20px; }\n    .g { display: grid; gap: 8px; margin-bottom: 12px; }\n    .g i { font-style: normal; background: #2563eb; color: white; padding: 12px; text-align: center; border-radius: 6px; }\n    .g1 { grid-template-columns: 1fr 1fr 1fr; }\n    .g2 { grid-template-columns: 1fr 2fr 1fr; }\n    .g3 { grid-template-columns: 120px 1fr; }\n    .g4 { grid-template-columns: repeat(3, 1fr); gap: 8px 20px; }\n  </style>\n</head>\n<body>\n  <div class=\"g g1\"><i>1fr</i><i>1fr</i><i>1fr</i></div>\n  <div class=\"g g2\"><i>1fr</i><i>2fr</i><i>1fr</i></div>\n  <div class=\"g g3\"><i>sabit</i><i>qalan yer</i></div>\n  <div class=\"g g4\"><i>1</i><i>2</i><i>3</i><i>4</i><i>5</i><i>6</i></div>\n</body>\n</html>\n"},
  {"id": "css-10-3", "lang": "css", "level": 10, "title": "Grid hüceyrələri birləşdirmək (span)", "keywords": ["grid-column", "grid-row", "span", "hüceyrə birləşdir", "объединить ячейки", "grid span", "böyük kart", "qeyri-bərabər grid", "bento"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Grid hüceyrələri birləşdirmək (span)</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 20px; }\n    .grid { display: grid; grid-template-columns: repeat(3, 1fr); grid-auto-rows: 70px; gap: 10px; }\n    .grid div { background: #0f766e; color: white; display: grid; place-items: center; border-radius: 10px; }\n    .a { grid-column: span 2; background: #2563eb !important; }\n    .d { grid-row: span 2; background: #7c3aed !important; }\n    .f { grid-column: 1 / -1; background: #db2777 !important; }\n  </style>\n</head>\n<body>\n  <div class=\"grid\">\n    <div class=\"a\">A (2 sütun)</div>\n    <div>B</div>\n    <div>C</div>\n    <div class=\"d\">D (2 sətir)</div>\n    <div>E</div>\n    <div class=\"f\">F (3 sütun)</div>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-10-4", "lang": "css", "level": 10, "title": "grid-template-areas", "keywords": ["grid-template-areas", "sahələr", "grid area", "ad ilə yerləşdirmə", "область сетки", "səhifə düzülüşü", "header sidebar main footer", "layout grid"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>grid-template-areas</title>\n  <style>\n    * { box-sizing: border-box; }\n    body { margin: 0; font-family: Arial, sans-serif; }\n    .sehife {\n      display: grid; min-height: 100vh; gap: 8px; padding: 8px;\n      grid-template-columns: 160px 1fr 160px;\n      grid-template-rows: auto 1fr auto;\n      grid-template-areas:\n        \"bas   bas    bas\"\n        \"menyu esas   yan\"\n        \"alt   alt    alt\";\n    }\n    header { grid-area: bas; } nav { grid-area: menyu; } main { grid-area: esas; } aside { grid-area: yan; } footer { grid-area: alt; }\n    .sehife > * { background: #ccfbf1; padding: 14px; border-radius: 8px; }\n    header, footer { background: #0b1b33; color: white; }\n  </style>\n</head>\n<body>\n  <div class=\"sehife\">\n    <header>Başlıq</header>\n    <nav>Menyu</nav>\n    <main>Əsas məzmun</main>\n    <aside>Reklamsız yan panel</aside>\n    <footer>Footer</footer>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-10-5", "lang": "css", "level": 10, "title": "auto-fit və minmax (responsiv grid)", "keywords": ["auto-fit", "auto-fill", "minmax", "responsiv grid", "медиазапросов не нужно", "avtomatik sütun", "ekrana uyğun", "adaptiv kartlar"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>auto-fit və minmax (responsiv grid)</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 20px; }\n    .grid { display: grid; gap: 12px; grid-template-columns: repeat(auto-fit, minmax(110px, 1fr)); }\n    .grid div { background: #0f766e; color: white; padding: 28px 10px; text-align: center; border-radius: 10px; font-weight: bold; }\n    p { color: #64748b; }\n  </style>\n</head>\n<body>\n  <div class=\"grid\">\n    <div>1</div><div>2</div><div>3</div><div>4</div><div>5</div><div>6</div><div>7</div>\n  </div>\n  <p>Pəncərəni daraldın: sütun sayı avtomatik dəyişir, @media lazım deyil.</p>\n</body>\n</html>\n"},
  {"id": "css-11-1", "lang": "css", "level": 11, "title": "Qalereya şəbəkəsi", "keywords": ["qalereya", "gallery", "foto şəbəkəsi", "image grid", "галерея", "masonry", "rəngli bloklar", "şəkil qalereyası", "grid gallery"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Qalereya şəbəkəsi</title>\n  <style>\n    body { margin: 0; padding: 16px; background: #0b1b33; font-family: Arial, sans-serif; }\n    .q { display: grid; grid-template-columns: repeat(4, 1fr); grid-auto-rows: 90px; gap: 10px; }\n    .q div { border-radius: 12px; display: grid; place-items: center; color: white; font-size: 24px; font-weight: bold; }\n    .b1 { grid-column: span 2; grid-row: span 2; background: linear-gradient(135deg, #0ea5e9, #6366f1); }\n    .b2 { background: #14b8a6; } .b3 { background: #f59e0b; }\n    .b4 { grid-row: span 2; background: #ec4899; } .b5 { background: #8b5cf6; }\n    .b6 { grid-column: span 2; background: #22c55e; } .b7 { background: #ef4444; }\n  </style>\n</head>\n<body>\n  <div class=\"q\">\n    <div class=\"b1\">1</div><div class=\"b2\">2</div><div class=\"b3\">3</div>\n    <div class=\"b4\">4</div><div class=\"b5\">5</div><div class=\"b6\">6</div><div class=\"b7\">7</div>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-11-2", "lang": "css", "level": 11, "title": "İdarə paneli düzülüşü", "keywords": ["dashboard layout", "idarə paneli", "admin panel", "sidebar dashboard", "панель управления", "statistika kartları", "yan menyu", "dashboard"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>İdarə paneli düzülüşü</title>\n  <style>\n    * { box-sizing: border-box; }\n    body { margin: 0; font-family: Arial, sans-serif; background: #f1f5f9; }\n    .app { display: grid; grid-template-columns: 170px 1fr; min-height: 100vh; }\n    aside { background: #0b1b33; color: #e2e8f0; padding: 18px; display: flex; flex-direction: column; gap: 10px; }\n    aside b { color: #5eead4; font-size: 18px; margin-bottom: 10px; }\n    aside a { color: #cbd5e1; text-decoration: none; padding: 8px 10px; border-radius: 8px; }\n    aside a:hover { background: #12294d; color: #5eead4; }\n    main { padding: 18px; display: grid; gap: 14px; grid-template-columns: repeat(3, 1fr); align-content: start; }\n    .stat { background: white; padding: 16px; border-radius: 12px; display: grid; gap: 4px; box-shadow: 0 4px 12px rgba(0, 0, 0, .06); }\n    .stat span { color: #64748b; font-size: 13px; } .stat strong { font-size: 26px; color: #0f766e; }\n    .qrafik { grid-column: span 2; height: 160px; background: white; border-radius: 12px; display: grid; place-items: center; color: #94a3b8; }\n    .siyahi { height: 160px; background: white; border-radius: 12px; display: grid; place-items: center; color: #94a3b8; }\n  </style>\n</head>\n<body>\n  <div class=\"app\">\n    <aside><b>Panel</b><a href=\"#\">İcmal</a><a href=\"#\">Hesabatlar</a><a href=\"#\">Ayarlar</a></aside>\n    <main>\n      <div class=\"stat\"><span>Ziyarət</span><strong>1 240</strong></div>\n      <div class=\"stat\"><span>İstifadəçi</span><strong>312</strong></div>\n      <div class=\"stat\"><span>Sorğu</span><strong>4 580</strong></div>\n      <div class=\"qrafik\">Qrafik sahəsi</div>\n      <div class=\"siyahi\">Son fəaliyyət</div>\n    </main>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-11-3", "lang": "css", "level": 11, "title": "Qiymət cədvəli kartları", "keywords": ["pricing", "qiymət planları", "tarif kartları", "pricing cards", "тарифы", "plan seçimi", "abunə kartı", "pulsuz plan", "features list"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Qiymət cədvəli kartları</title>\n  <style>\n    body { font-family: Arial, sans-serif; background: #0b1b33; padding: 30px; }\n    .planlar { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 18px; max-width: 760px; margin: auto; align-items: center; }\n    .plan { background: #12294d; color: #e2e8f0; padding: 24px; border-radius: 16px; text-align: center; }\n    .plan h3 { margin: 0; color: #5eead4; }\n    .q { font-size: 34px; font-weight: bold; margin: 10px 0; } .q small { font-size: 14px; color: #94a3b8; }\n    .plan ul { list-style: none; padding: 0; margin: 0 0 18px; color: #cbd5e1; line-height: 2; }\n    .plan a { display: block; background: #14b8a6; color: #042f2e; padding: 10px; border-radius: 10px; text-decoration: none; font-weight: bold; }\n    .secilmis { border: 2px solid #14b8a6; transform: scale(1.05); }\n  </style>\n</head>\n<body>\n  <div class=\"planlar\">\n    <div class=\"plan\"><h3>Pulsuz</h3><p class=\"q\">0 ₼</p><ul><li>Əsas funksiyalar</li><li>Reklamsız</li></ul><a href=\"#\">Başla</a></div>\n    <div class=\"plan secilmis\"><h3>Premium</h3><p class=\"q\">5 ₼<small>/ay</small></p><ul><li>Bütün funksiyalar</li><li>Ek imkanlar</li><li>Prioritet dəstək</li></ul><a href=\"#\">Seç</a></div>\n    <div class=\"plan\"><h3>Komanda</h3><p class=\"q\">15 ₼<small>/ay</small></p><ul><li>5 istifadəçi</li><li>Ortaq qovluq</li></ul><a href=\"#\">Seç</a></div>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-11-4", "lang": "css", "level": 11, "title": "Jurnal düzülüşü", "keywords": ["magazine layout", "jurnal", "xəbər səhifəsi", "news layout", "газетный макет", "böyük xəbər", "kiçik xəbərlər", "grid-template-areas", "blog səhifəsi"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Jurnal düzülüşü</title>\n  <style>\n    body { font-family: Georgia, serif; background: #f8fafc; padding: 20px; }\n    .jurnal { display: grid; gap: 12px; max-width: 700px; margin: auto;\n      grid-template-columns: 2fr 1fr 1fr;\n      grid-template-areas: \"esas esas x1\" \"esas esas x2\" \"x3 x4 x4\"; }\n    article { background: white; border: 1px solid #e2e8f0; padding: 14px; border-radius: 6px; }\n    .esas { grid-area: esas; background: #0b1b33; color: white; display: flex; flex-direction: column; justify-content: end; min-height: 180px; }\n    .esas small { color: #5eead4; letter-spacing: 2px; } .esas h2 { margin: 6px 0; }\n    .x1 { grid-area: x1; } .x2 { grid-area: x2; } .x3 { grid-area: x3; } .x4 { grid-area: x4; }\n    h4 { margin: 0; color: #0f766e; }\n  </style>\n</head>\n<body>\n  <div class=\"jurnal\">\n    <article class=\"esas\"><small>XƏBƏR</small><h2>Əsas xəbərin başlığı burada yazılır</h2><p>Qısa təsvir mətni.</p></article>\n    <article class=\"x1\"><h4>İkinci xəbər</h4></article>\n    <article class=\"x2\"><h4>Üçüncü xəbər</h4></article>\n    <article class=\"x3\"><h4>Dördüncü xəbər</h4></article>\n    <article class=\"x4\"><h4>Beşinci xəbər</h4></article>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-11-5", "lang": "css", "level": 11, "title": "Təqvim şəbəkəsi", "keywords": ["təqvim", "calendar", "ay təqvimi", "calendar grid", "календарь", "günlər", "7 sütun", "bu ayın günləri", "aylıq təqvim"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Təqvim şəbəkəsi</title>\n  <style>\n    body { font-family: Arial, sans-serif; background: #0b1b33; display: grid; place-items: center; min-height: 100vh; margin: 0; }\n    .tq { background: #12294d; color: #e2e8f0; padding: 18px; border-radius: 16px; width: 300px; }\n    .tq h3 { margin: 0 0 12px; text-align: center; color: #5eead4; }\n    .gunler { display: grid; grid-template-columns: repeat(7, 1fr); gap: 4px; text-align: center; }\n    .gunler b { font-size: 12px; color: #94a3b8; padding-bottom: 6px; }\n    .gunler span { padding: 8px 0; border-radius: 8px; }\n    .gunler span:not(.bos):hover { background: #1e3a66; }\n    .bu { background: #14b8a6; color: #042f2e; font-weight: bold; }\n  </style>\n</head>\n<body>\n  <div class=\"tq\">\n    <h3>Oktyabr 2026</h3>\n    <div class=\"gunler\">\n      <b>B.e</b><b>Ç.a</b><b>Çər</b><b>C.a</b><b>Cüm</b><b>Şən</b><b>Baz</b>\n      <span class=\"bos\"></span><span class=\"bos\"></span><span class=\"bos\"></span>\n      <span>1</span><span>2</span><span class=\"bu\">3</span><span>4</span>\n      <span>5</span><span>6</span><span>7</span><span>8</span><span>9</span><span>10</span><span>11</span>\n      <span>12</span><span>13</span><span>14</span><span>15</span><span>16</span><span>17</span><span>18</span>\n    </div>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-12-1", "lang": "css", "level": 12, "title": "transition ilə hover effekti", "keywords": ["transition", "keçid effekti", "hover animasiya", "yumşaq keçid", "переход", "plavno", "duration", "easing", "düymə effekti"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>transition ilə hover effekti</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 30px; background: #f1f5f9; }\n    .d { padding: 14px 28px; border: 0; border-radius: 10px; background: #0f766e; color: white; font-size: 16px; cursor: pointer;\n      transition: background .3s ease, transform .3s ease, box-shadow .3s ease; }\n    .d:hover { background: #14b8a6; transform: translateY(-3px); box-shadow: 0 10px 20px rgba(15, 118, 110, .35); }\n    .k { margin-top: 24px; width: 160px; padding: 30px; background: white; border-radius: 14px; transition: transform .3s, box-shadow .3s; }\n    .k:hover { transform: scale(1.08); box-shadow: 0 14px 30px rgba(15, 23, 42, .2); }\n  </style>\n</head>\n<body>\n  <button class=\"d\">Üzərinə gəl</button>\n  <div class=\"k\">Kart</div>\n</body>\n</html>\n"},
  {"id": "css-12-2", "lang": "css", "level": 12, "title": "transform: scale, rotate", "keywords": ["transform", "scale", "rotate", "böyüt", "fırlat", "поворот", "масштаб", "çevir", "bucaq", "deg"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>transform: scale, rotate</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 50px 30px; }\n    .s { display: flex; gap: 50px; }\n    .k { width: 90px; height: 90px; background: #0f766e; color: white; display: grid; place-items: center; text-align: center; border-radius: 12px; font-size: 14px; }\n    .scale { transform: scale(1.3); }\n    .rotate { transform: rotate(20deg); background: #2563eb; }\n    .hover { background: #db2777; transition: transform .5s; }\n    .hover:hover { transform: rotate(360deg) scale(1.2); }\n  </style>\n</head>\n<body>\n  <div class=\"s\">\n    <div class=\"k scale\">scale(1.3)</div>\n    <div class=\"k rotate\">rotate(20deg)</div>\n    <div class=\"k hover\">hover et</div>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-12-3", "lang": "css", "level": 12, "title": "translate, skew və transform-origin", "keywords": ["translate", "skew", "transform-origin", "sürüşdür", "əyri", "перемещение", "наклон", "birləşdirilmiş transform", "matrix"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>translate, skew və transform-origin</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 60px 30px; }\n    .s { display: flex; gap: 40px; flex-wrap: wrap; }\n    .k { width: 90px; height: 70px; background: #0f766e; color: white; display: grid; place-items: center; border-radius: 8px; font-size: 14px; }\n    .t { transform: translate(20px, -20px); }\n    .e { transform: skew(-15deg, 5deg); background: #7c3aed; }\n    .o { transform-origin: top left; transform: rotate(15deg); background: #db2777; }\n    .h { transform: translateX(10px) rotate(8deg) scale(1.1) skewX(-6deg); background: #f59e0b; }\n  </style>\n</head>\n<body>\n  <div class=\"s\">\n    <div class=\"k t\">translate</div>\n    <div class=\"k e\">skew</div>\n    <div class=\"k o\">origin</div>\n    <div class=\"k h\">hamısı</div>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-12-4", "lang": "css", "level": 12, "title": "3D kart çevirmə (flip)", "keywords": ["flip card", "3d çevirmə", "perspective", "backface-visibility", "переворот карточки", "kartı çevir", "hover flip", "transform-style", "3d effekt"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>3D kart çevirmə (flip)</title>\n  <style>\n    body { margin: 0; min-height: 100vh; display: grid; place-items: center; background: #0b1b33; font-family: Arial, sans-serif; }\n    .sahne { width: 220px; height: 280px; perspective: 800px; }\n    .kart { position: relative; width: 100%; height: 100%; transform-style: preserve-3d; transition: transform .8s; }\n    .sahne:hover .kart { transform: rotateY(180deg); }\n    .uz { position: absolute; inset: 0; display: grid; place-items: center; text-align: center; border-radius: 18px; font-size: 22px; font-weight: bold; backface-visibility: hidden; }\n    .on { background: linear-gradient(135deg, #14b8a6, #2563eb); color: white; }\n    .arxa { background: #f8fafc; color: #0b1b33; transform: rotateY(180deg); }\n  </style>\n</head>\n<body>\n  <div class=\"sahne\">\n    <div class=\"kart\">\n      <div class=\"uz on\">Ön üz<br><small>(üzərinə gəl)</small></div>\n      <div class=\"uz arxa\">Arxa üz<br>Məlumat burada</div>\n    </div>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-12-5", "lang": "css", "level": 12, "title": "Hover düymə effektləri", "keywords": ["düymə effektləri", "button hover", "doldurma effekti", "border animasiya", "кнопки hover", "slide fill", "underline animasiya", "ripple alternativ"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Hover düymə effektləri</title>\n  <style>\n    body { font-family: Arial, sans-serif; background: #f8fafc; padding: 40px; }\n    .s { display: flex; gap: 30px; align-items: center; }\n    button { padding: 12px 24px; font-size: 16px; border-radius: 10px; cursor: pointer; }\n    .d1 { border: 2px solid #0f766e; color: #0f766e; background: linear-gradient(#0f766e, #0f766e) no-repeat left / 0% 100%; transition: background-size .35s, color .35s; }\n    .d1:hover { background-size: 100% 100%; color: white; }\n    .d2 { border: 0; background: #0f766e; color: white; box-shadow: 0 6px 0 #134e4a; transition: transform .1s, box-shadow .1s; }\n    .d2:hover { transform: translateY(3px); box-shadow: 0 3px 0 #134e4a; }\n    .d2:active { transform: translateY(6px); box-shadow: 0 0 0 #134e4a; }\n    .d3 { color: #0f172a; text-decoration: none; font-size: 18px; background: linear-gradient(#14b8a6, #14b8a6) no-repeat left bottom / 0% 3px; transition: background-size .3s; }\n    .d3:hover { background-size: 100% 3px; }\n  </style>\n</head>\n<body>\n  <div class=\"s\">\n    <button class=\"d1\">Soldan dol</button>\n    <button class=\"d2\">Kölgə</button>\n    <a class=\"d3\" href=\"#\">Alt xətt</a>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-13-1", "lang": "css", "level": 13, "title": "@keyframes ilə sıçrayan top", "keywords": ["keyframes", "animation", "animasiya", "sıçrama", "bounce", "анимация", "@keyframes", "animation-name", "sonsuz animasiya", "top"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>@keyframes ilə sıçrayan top</title>\n  <style>\n    body { margin: 0; background: #0b1b33; display: grid; place-items: center; min-height: 100vh; }\n    .yer { height: 200px; width: 100px; position: relative; border-bottom: 4px solid #1e3a66; }\n    .top { position: absolute; left: 25px; bottom: 0; width: 50px; height: 50px; border-radius: 50%; background: #2dd4bf;\n      animation: sicra 1s cubic-bezier(.3, 0, .7, 1) infinite alternate; }\n    @keyframes sicra {\n      from { transform: translateY(0); }\n      to   { transform: translateY(-140px); }\n    }\n  </style>\n</head>\n<body>\n  <div class=\"yer\"><div class=\"top\"></div></div>\n</body>\n</html>\n"},
  {"id": "css-13-2", "lang": "css", "level": 13, "title": "Yavaş-yavaş görünmə (fade in)", "keywords": ["fade in", "görünmə", "appear", "появление", "animation-delay", "ardıcıl görünmə", "stagger", "giriş animasiyası", "slide up"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Yavaş-yavaş görünmə (fade in)</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 40px; background: #f8fafc; }\n    .g { opacity: 0; animation: gorun .8s ease forwards; }\n    .d1 { animation-delay: .4s; }\n    .d2 { animation-delay: .8s; }\n    @keyframes gorun {\n      from { opacity: 0; transform: translateY(20px); }\n      to   { opacity: 1; transform: translateY(0); }\n    }\n  </style>\n</head>\n<body>\n  <h1 class=\"g\">Xoş gəldiniz</h1>\n  <p class=\"g d1\">Bu mətn gecikmə ilə görünür.</p>\n  <p class=\"g d2\">Sonuncu sətir də ardınca gəlir.</p>\n</body>\n</html>\n"},
  {"id": "css-13-3", "lang": "css", "level": 13, "title": "Pulsasiya və döyünmə", "keywords": ["pulse", "pulsasiya", "döyünmə", "bildiriş nöqtəsi", "пульсация", "canlı nöqtə", "live indicator", "nəfəs alan", "heartbeat alternativ"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Pulsasiya və döyünmə</title>\n  <style>\n    body { font-family: Arial, sans-serif; background: #0b1b33; color: #e2e8f0; padding: 40px; }\n    .s { display: flex; align-items: center; gap: 12px; margin-bottom: 30px; }\n    .nokta { width: 14px; height: 14px; border-radius: 50%; background: #22c55e; animation: nabz 1.6s infinite; }\n    @keyframes nabz {\n      0% { box-shadow: 0 0 0 0 rgba(34, 197, 94, .7); }\n      70% { box-shadow: 0 0 0 14px rgba(34, 197, 94, 0); }\n      100% { box-shadow: 0 0 0 0 rgba(34, 197, 94, 0); }\n    }\n    .d { padding: 14px 28px; border: 0; border-radius: 10px; background: #14b8a6; color: #042f2e; font-weight: bold; animation: boyu 1.4s ease-in-out infinite; }\n    @keyframes boyu { 50% { transform: scale(1.08); } }\n  </style>\n</head>\n<body>\n  <div class=\"s\"><span class=\"nokta\"></span> Onlayn</div>\n  <button class=\"d\">Diqqət çək</button>\n</body>\n</html>\n"},
  {"id": "css-13-4", "lang": "css", "level": 13, "title": "Yazı yazılma effekti", "keywords": ["typing effect", "yazı effekti", "daktilo", "typewriter", "печатная машинка", "steps", "caret", "kursor yanıb-sönür", "animasiyalı mətn"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Yazı yazılma effekti</title>\n  <style>\n    body { margin: 0; min-height: 100vh; display: grid; place-items: center; background: #0b1b33; }\n    .yaz {\n      font-family: \"Courier New\", monospace; color: #5eead4; font-size: 28px;\n      width: 22ch; white-space: nowrap; overflow: hidden;\n      border-right: 3px solid #5eead4;\n      animation: yazilir 3s steps(22) infinite alternate, kursor .7s step-end infinite;\n    }\n    @keyframes yazilir { from { width: 0; } to { width: 22ch; } }\n    @keyframes kursor { 50% { border-color: transparent; } }\n  </style>\n</head>\n<body>\n  <h1 class=\"yaz\">Nibras Code ilə öyrən</h1>\n</body>\n</html>\n"},
  {"id": "css-13-5", "lang": "css", "level": 13, "title": "Fırlanan yükləmə və gradient animasiyası", "keywords": ["gradient animation", "fırlanan", "rotate infinite", "animasiyalı fon", "анимированный градиент", "rəng dəyişən fon", "background-position animation", "spin"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Fırlanan yükləmə və gradient animasiyası</title>\n  <style>\n    body { margin: 0; font-family: Arial, sans-serif; background: #0b1b33; color: white; display: grid; gap: 30px; justify-items: center; padding: 30px; }\n    .fon { width: 320px; height: 120px; border-radius: 16px; display: grid; place-items: center;\n      background: linear-gradient(120deg, #14b8a6, #2563eb, #7c3aed, #14b8a6); background-size: 300% 300%; animation: axin 6s ease infinite; }\n    @keyframes axin { 0% { background-position: 0% 50%; } 50% { background-position: 100% 50%; } 100% { background-position: 0% 50%; } }\n    .fir { width: 60px; height: 60px; border-radius: 14px; background: #f59e0b; animation: don 2s linear infinite; }\n    @keyframes don { to { transform: rotate(360deg); } }\n  </style>\n</head>\n<body>\n  <div class=\"fon\"><h2>Hərəkətli fon</h2></div>\n  <div class=\"fir\"></div>\n</body>\n</html>\n"},
  {"id": "css-14-1", "lang": "css", "level": 14, "title": "@media sorğusu: ekran ölçüsünə görə", "keywords": ["media query", "@media", "responsiv", "max-width", "mobil", "адаптивность", "ekran ölçüsü", "breakpoint", "telefon üçün"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>@media sorğusu: ekran ölçüsünə görə</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 20px; }\n    .qutu { padding: 30px; color: white; text-align: center; font-size: 20px; border-radius: 12px; background: #16a34a; }\n    @media (max-width: 800px) { .qutu { background: #2563eb; } }\n    @media (max-width: 480px) { .qutu { background: #dc2626; font-size: 15px; } }\n    .not { color: #64748b; }\n  </style>\n</head>\n<body>\n  <div class=\"qutu\">Pəncərənin enini dəyişin</div>\n  <p class=\"not\">Geniş ekranda yaşıl, orta ekranda mavi, kiçik ekranda qırmızı olur.</p>\n</body>\n</html>\n"},
  {"id": "css-14-2", "lang": "css", "level": 14, "title": "Responsiv naviqasiya", "keywords": ["responsiv menyu", "mobil menyu", "hamburger alternativ", "адаптивное меню", "nav mobile", "menyu alt-alta", "kiçik ekranda menyu"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Responsiv naviqasiya</title>\n  <style>\n    body { margin: 0; font-family: Arial, sans-serif; }\n    .nav { display: flex; justify-content: space-between; align-items: center; padding: 14px 20px; background: #0b1b33; }\n    .logo { color: #5eead4; font-size: 20px; }\n    .linkler { display: flex; gap: 18px; }\n    .linkler a { color: #e2e8f0; text-decoration: none; }\n    .not { padding: 20px; color: #64748b; }\n    @media (max-width: 600px) {\n      .nav { flex-direction: column; gap: 10px; }\n      .linkler { flex-wrap: wrap; justify-content: center; gap: 10px 16px; }\n    }\n  </style>\n</head>\n<body>\n  <nav class=\"nav\">\n    <b class=\"logo\">Nibras</b>\n    <div class=\"linkler\"><a href=\"#\">Ana</a><a href=\"#\">Tətbiqlər</a><a href=\"#\">Haqqında</a><a href=\"#\">Əlaqə</a></div>\n  </nav>\n  <p class=\"not\">Pəncərəni 600px-dən kiçik edin.</p>\n</body>\n</html>\n"},
  {"id": "css-14-3", "lang": "css", "level": 14, "title": "Responsiv kartlar şəbəkəsi", "keywords": ["responsive grid", "kart şəbəkəsi", "1 2 3 sütun", "адаптивная сетка", "mobil planşet masaüstü", "breakpoint grid", "kartlar ekrana uyğun"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Responsiv kartlar şəbəkəsi</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 16px; background: #f1f5f9; }\n    .grid { display: grid; gap: 14px; grid-template-columns: 1fr; }          /* mobil: 1 sütun */\n    @media (min-width: 600px) { .grid { grid-template-columns: repeat(2, 1fr); } }   /* planşet: 2 */\n    @media (min-width: 900px) { .grid { grid-template-columns: repeat(3, 1fr); } }   /* kompüter: 3 */\n    .kart { background: white; padding: 36px 16px; text-align: center; border-radius: 12px; font-weight: bold; color: #0f766e; box-shadow: 0 4px 10px rgba(0, 0, 0, .06); }\n  </style>\n</head>\n<body>\n  <div class=\"grid\">\n    <div class=\"kart\">Kart 1</div><div class=\"kart\">Kart 2</div><div class=\"kart\">Kart 3</div>\n    <div class=\"kart\">Kart 4</div><div class=\"kart\">Kart 5</div><div class=\"kart\">Kart 6</div>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-14-4", "lang": "css", "level": 14, "title": "clamp() ilə axıcı şrift", "keywords": ["clamp", "fluid typography", "axıcı şrift ölçüsü", "vw", "vh", "min max", "резиновая типографика", "ekrana görə şrift", "responsiv başlıq", "min() max()"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>clamp() ilə axıcı şrift</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 20px; }\n    h1 { font-size: clamp(1.4rem, 5vw, 3rem); color: #0f766e; }\n    p { font-size: clamp(1rem, 2.2vw, 1.4rem); }\n    .blok { width: min(90%, 500px); margin-top: 20px; padding: 24px; background: #ccfbf1; border-radius: 12px; text-align: center; }\n  </style>\n</head>\n<body>\n  <h1>Ekranla birlikdə böyüyən başlıq</h1>\n  <p>Bu paraqraf da clamp() ilə ölçülür. Pəncərəni genişləndirib daraldın.</p>\n  <div class=\"blok\">min(90%, 500px)</div>\n</body>\n</html>\n"},
  {"id": "css-14-5", "lang": "css", "level": 14, "title": "Container query", "keywords": ["container query", "@container", "komponent ölçüsü", "контейнерные запросы", "container-type", "kart içi layout", "modern responsiv", "element ölçüsünə görə"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Container query</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 20px; background: #f1f5f9; }\n    .qab { container-type: inline-size; margin-bottom: 20px; }\n    .dar { width: 220px; } .genis { width: 480px; }\n    .kart { display: grid; gap: 10px; background: white; padding: 12px; border-radius: 12px; }\n    .foto { height: 70px; background: linear-gradient(135deg, #14b8a6, #2563eb); border-radius: 8px; }\n    h3 { margin: 0; color: #0f766e; } p { margin: 4px 0 0; color: #64748b; font-size: 14px; }\n    @container (min-width: 400px) { .kart { grid-template-columns: 140px 1fr; align-items: center; } .foto { height: 90px; } }\n  </style>\n</head>\n<body>\n  <div class=\"qab dar\"><article class=\"kart\"><div class=\"foto\"></div><div><h3>Kart</h3><p>Container enindən asılı düzülür.</p></div></article></div>\n  <div class=\"qab genis\"><article class=\"kart\"><div class=\"foto\"></div><div><h3>Kart</h3><p>Container enindən asılı düzülür.</p></div></article></div>\n</body>\n</html>\n"},
  {"id": "css-15-1", "lang": "css", "level": 15, "title": "CSS dəyişənləri (custom properties)", "keywords": ["css variables", "custom properties", "--dəyişən", "var()", "переменные css", "rəng dəyişəni", "tema dəyişənləri", ":root", "mərkəzi rənglər"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>CSS dəyişənləri (custom properties)</title>\n  <style>\n    :root {\n      --esas: #0f766e;\n      --fon: #f0fdfa;\n      --bosluq: 16px;\n      --radius: 14px;\n    }\n    body { font-family: Arial, sans-serif; padding: 24px; background: var(--fon); }\n    .kart { background: white; padding: calc(var(--bosluq) * 1.5); border-radius: var(--radius); border-top: 6px solid var(--esas); max-width: 300px; }\n    h3 { color: var(--esas); margin-top: 0; }\n    button { background: var(--esas); color: white; border: 0; padding: 10px 18px; border-radius: var(--radius); }\n  </style>\n</head>\n<body>\n  <div class=\"kart\"><h3>Başlıq</h3><p>Rənglər :root-dakı dəyişənlərdən gəlir.</p><button>Düymə</button></div>\n</body>\n</html>\n"},
  {"id": "css-15-2", "lang": "css", "level": 15, "title": "Tünd və açıq rejim düyməsi", "keywords": ["dark mode", "tünd rejim", "açıq rejim", "theme toggle", "тёмная тема", "dark light", "tema dəyiş", "data-theme", "localstorage olmadan"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Tünd və açıq rejim düyməsi</title>\n  <style>\n    :root { --fon: #f8fafc; --yazi: #0f172a; --kart: #ffffff; --esas: #0f766e; }\n    [data-theme=\"tund\"] { --fon: #0b1b33; --yazi: #e2e8f0; --kart: #12294d; --esas: #2dd4bf; }\n    body { margin: 0; min-height: 100vh; display: grid; place-items: center; background: var(--fon); color: var(--yazi); font-family: Arial, sans-serif; transition: background .3s, color .3s; }\n    .kart { background: var(--kart); padding: 28px; border-radius: 16px; max-width: 320px; box-shadow: 0 10px 30px rgba(0, 0, 0, .15); transition: background .3s; }\n    h2 { margin-top: 0; color: var(--esas); }\n    button { border: 0; padding: 10px 18px; border-radius: 10px; background: var(--esas); color: var(--fon); font-weight: bold; cursor: pointer; }\n  </style>\n</head>\n<body>\n  <div class=\"kart\">\n    <h2>Tema dəyişmə</h2>\n    <p>Düyməyə basın: səhifənin rəngləri dəyişəcək.</p>\n    <button id=\"duyme\">🌙 Tünd rejim</button>\n  </div>\n  <script>\n    const duyme = document.getElementById(\"duyme\");\n    duyme.addEventListener(\"click\", () => {\n      const tund = document.documentElement.dataset.theme === \"tund\";\n      document.documentElement.dataset.theme = tund ? \"\" : \"tund\";\n      duyme.textContent = tund ? \"🌙 Tünd rejim\" : \"☀ Açıq rejim\";\n    });\n  </script>\n</body>\n</html>\n"},
  {"id": "css-15-3", "lang": "css", "level": 15, "title": "Sistem rejiminə uyğun tema", "keywords": ["prefers-color-scheme", "sistem teması", "avtomatik dark mode", "системная тема", "color-scheme", "operasiya sistemi teması", "otomatik tema"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Sistem rejiminə uyğun tema</title>\n  <style>\n    :root { color-scheme: light dark; --fon: #f8fafc; --yazi: #0f172a; --kart: #fff; }\n    @media (prefers-color-scheme: dark) {\n      :root { --fon: #0b1b33; --yazi: #e2e8f0; --kart: #12294d; }\n    }\n    body { margin: 0; min-height: 100vh; display: grid; place-items: center; background: var(--fon); color: var(--yazi); font-family: Arial, sans-serif; }\n    .kart { background: var(--kart); padding: 28px; border-radius: 16px; max-width: 320px; border: 1px solid rgba(148, 163, 184, .4); }\n    h2 { margin-top: 0; }\n  </style>\n</head>\n<body>\n  <div class=\"kart\"><h2>Avtomatik tema</h2><p>Cihazınız tünd rejimdədirsə bu kart da tünd görünür.</p></div>\n</body>\n</html>\n"},
  {"id": "css-15-4", "lang": "css", "level": 15, "title": "HSL ilə rəng palitrası", "keywords": ["hsl palette", "rəng palitrası", "color palette", "палитра цветов", "hsl dəyişən", "ton açıq tünd", "color scale", "calc hsl", "əsas rəngdən çalarlar"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>HSL ilə rəng palitrası</title>\n  <style>\n    :root { --ton: 172; --doyma: 66%; }   /* ton dəyişsə bütün palitra dəyişir */\n    body { font-family: Arial, sans-serif; padding: 24px; background: #fff; }\n    .palitra { display: flex; border-radius: 14px; overflow: hidden; max-width: 520px; }\n    .palitra div { flex: 1; padding: 40px 0 8px; text-align: center; font-size: 12px;\n      background: hsl(var(--ton), var(--doyma), var(--a)); color: white; }\n    .palitra div:nth-child(-n+4) { color: #0f172a; }\n  </style>\n</head>\n<body>\n  <div class=\"palitra\">\n    <div style=\"--a:95%\">50</div><div style=\"--a:85%\">100</div><div style=\"--a:70%\">200</div>\n    <div style=\"--a:55%\">300</div><div style=\"--a:42%\">400</div><div style=\"--a:32%\">500</div><div style=\"--a:22%\">600</div><div style=\"--a:14%\">700</div>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-15-5", "lang": "css", "level": 15, "title": "Boşluq şkalası və calc()", "keywords": ["calc", "spacing scale", "boşluq şkalası", "calc() hesablama", "расчеты в css", "dizayn sistemi", "rem vahid", "əsas ölçü", "sabit aralıqlar"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Boşluq şkalası və calc()</title>\n  <style>\n    :root { --bosluq: 8px; }\n    body { font-family: Arial, sans-serif; padding: 20px; }\n    .s { background: #14b8a6; color: #042f2e; margin-bottom: var(--bosluq); border-radius: 6px; }\n    .s1 { padding: calc(var(--bosluq) * 1); }\n    .s2 { padding: calc(var(--bosluq) * 2); }\n    .s3 { padding: calc(var(--bosluq) * 3); }\n    .s4 { padding: var(--bosluq); width: calc(100% - 40px); background: #5eead4; }\n  </style>\n</head>\n<body>\n  <div class=\"s s1\">--bosluq × 1</div>\n  <div class=\"s s2\">--bosluq × 2</div>\n  <div class=\"s s3\">--bosluq × 3</div>\n  <div class=\"s s4\">calc(100% - 40px)</div>\n</body>\n</html>\n"},
  {"id": "css-16-1", "lang": "css", "level": 16, "title": "Düymə dəsti", "keywords": ["düymələr", "buttons", "button styles", "кнопки", "düymə növləri", "primary secondary", "outline düymə", "ölçülü düymələr", "disabled düymə"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Düymə dəsti</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 24px; background: #f8fafc; }\n    .s { display: flex; gap: 10px; flex-wrap: wrap; align-items: center; margin-bottom: 18px; }\n    .d { padding: 10px 20px; border: 2px solid transparent; border-radius: 10px; font-size: 15px; font-weight: bold; cursor: pointer; transition: filter .2s, transform .1s; }\n    .d:hover:not(:disabled) { filter: brightness(1.1); }\n    .d:active:not(:disabled) { transform: scale(.97); }\n    .esas { background: #0f766e; color: white; }\n    .ikinci { background: #e2e8f0; color: #0f172a; }\n    .kontur { background: transparent; border-color: #0f766e; color: #0f766e; }\n    .tehlukeli { background: #dc2626; color: white; }\n    .d:disabled { opacity: .45; cursor: not-allowed; }\n    .kicik { padding: 5px 12px; font-size: 13px; } .boyuk { padding: 14px 32px; font-size: 18px; }\n  </style>\n</head>\n<body>\n  <div class=\"s\">\n    <button class=\"d esas\">Əsas</button>\n    <button class=\"d ikinci\">İkinci</button>\n    <button class=\"d kontur\">Kontur</button>\n    <button class=\"d tehlukeli\">Sil</button>\n    <button class=\"d esas\" disabled>Passiv</button>\n  </div>\n  <div class=\"s\">\n    <button class=\"d esas kicik\">Kiçik</button>\n    <button class=\"d esas boyuk\">Böyük</button>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-16-2", "lang": "css", "level": 16, "title": "Kart komponenti", "keywords": ["kart", "card", "məhsul kartı", "profil kartı", "карточка", "card component", "başlıq mətn düymə", "kart dizaynı"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Kart komponenti</title>\n  <style>\n    body { font-family: Arial, sans-serif; background: #e2e8f0; display: grid; place-items: center; min-height: 100vh; margin: 0; }\n    .kart { width: 280px; background: white; border-radius: 18px; overflow: hidden; box-shadow: 0 14px 34px rgba(15, 23, 42, .18); transition: transform .25s; }\n    .kart:hover { transform: translateY(-6px); }\n    .tepe { height: 120px; background: linear-gradient(135deg, #14b8a6, #2563eb); padding: 12px; }\n    .nisan { background: white; color: #0f766e; font-size: 12px; font-weight: bold; padding: 4px 10px; border-radius: 999px; }\n    .bed { padding: 18px; }\n    h3 { margin: 0 0 6px; } p { margin: 0 0 16px; color: #64748b; font-size: 14px; line-height: 1.5; }\n    .alt { display: flex; justify-content: space-between; align-items: center; }\n    .alt a { background: #0f766e; color: white; text-decoration: none; padding: 8px 16px; border-radius: 10px; font-size: 14px; }\n  </style>\n</head>\n<body>\n  <article class=\"kart\">\n    <div class=\"tepe\"><span class=\"nisan\">Yeni</span></div>\n    <div class=\"bed\">\n      <h3>Python kursu</h3>\n      <p>Sıfırdan başlayanlar üçün 20 səviyyəlik kod nümunələri.</p>\n      <div class=\"alt\"><strong>Pulsuz</strong><a href=\"#\">Bax</a></div>\n    </div>\n  </article>\n</body>\n</html>\n"},
  {"id": "css-16-3", "lang": "css", "level": 16, "title": "Form elementlərinin stili", "keywords": ["form stili", "input stili", "form styling", "форма стили", "input select textarea", "etiket və sahə", "giriş forması", "qeydiyyat forması"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Form elementlərinin stili</title>\n  <style>\n    body { font-family: Arial, sans-serif; background: #0b1b33; display: grid; place-items: center; min-height: 100vh; margin: 0; }\n    .f { width: 300px; background: white; padding: 24px; border-radius: 16px; display: grid; gap: 14px; }\n    h2 { margin: 0; color: #0f766e; }\n    label { display: grid; gap: 4px; font-size: 14px; color: #475569; }\n    input, select, textarea { font: inherit; padding: 10px 12px; border: 2px solid #cbd5e1; border-radius: 10px; outline: none; transition: border-color .2s, box-shadow .2s; }\n    input:focus, select:focus, textarea:focus { border-color: #14b8a6; box-shadow: 0 0 0 4px rgba(20, 184, 166, .2); }\n    button { padding: 12px; border: 0; border-radius: 10px; background: #0f766e; color: white; font-size: 16px; font-weight: bold; cursor: pointer; }\n  </style>\n</head>\n<body>\n  <form class=\"f\" onsubmit=\"return false\">\n    <h2>Qeydiyyat</h2>\n    <label>Ad<input type=\"text\" placeholder=\"Adınız\"></label>\n    <label>E-poçt<input type=\"email\" placeholder=\"ad@mail.az\"></label>\n    <label>Ölkə<select><option>Azərbaycan</option><option>Türkiyə</option><option>Digər</option></select></label>\n    <label>Mesaj<textarea rows=\"3\" placeholder=\"Qısa mesaj\"></textarea></label>\n    <button>Göndər</button>\n  </form>\n</body>\n</html>\n"},
  {"id": "css-16-4", "lang": "css", "level": 16, "title": "Bildiriş qutuları və nişanlar", "keywords": ["alert", "badge", "bildiriş", "notification", "уведомления", "uğur xəta xəbərdarlıq", "xəbərdarlıq qutusu", "status etiketi", "toast"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Bildiriş qutuları və nişanlar</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 24px; max-width: 420px; }\n    .alert { padding: 12px 16px; border-radius: 10px; margin-bottom: 10px; border-left: 5px solid; }\n    .ok { background: #dcfce7; border-color: #16a34a; color: #14532d; }\n    .info { background: #dbeafe; border-color: #2563eb; color: #1e3a8a; }\n    .xeb { background: #fef3c7; border-color: #d97706; color: #78350f; }\n    .xeta { background: #fee2e2; border-color: #dc2626; color: #7f1d1d; }\n    .b { padding: 3px 10px; border-radius: 999px; font-size: 12px; font-weight: bold; }\n    .yeni { background: #e0e7ff; color: #3730a3; } .aktiv { background: #dcfce7; color: #166534; }\n    .gozle { background: #fef3c7; color: #92400e; } .bagli { background: #e2e8f0; color: #475569; }\n  </style>\n</head>\n<body>\n  <div class=\"alert ok\">✔ Əməliyyat uğurla tamamlandı.</div>\n  <div class=\"alert info\">ℹ Yeni versiya mövcuddur.</div>\n  <div class=\"alert xeb\">⚠ Yaddaş dolmaq üzrədir.</div>\n  <div class=\"alert xeta\">✖ Xəta baş verdi, yenidən yoxlayın.</div>\n  <p><span class=\"b yeni\">Yeni</span> <span class=\"b aktiv\">Aktiv</span> <span class=\"b gozle\">Gözləyir</span> <span class=\"b bagli\">Bağlı</span></p>\n</body>\n</html>\n"},
  {"id": "css-16-5", "lang": "css", "level": 16, "title": "Cədvəl stili", "keywords": ["table", "cədvəl", "zebra cədvəl", "table styling", "таблица стили", "border-collapse", "sətir hover", "cədvəl dizaynı"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Cədvəl stili</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 24px; background: #f1f5f9; }\n    table { border-collapse: collapse; width: 100%; max-width: 460px; background: white; border-radius: 12px; overflow: hidden; box-shadow: 0 6px 16px rgba(15, 23, 42, .1); }\n    th { background: #0f766e; color: white; text-align: left; padding: 12px 14px; }\n    td { padding: 11px 14px; border-bottom: 1px solid #e2e8f0; }\n    tbody tr:nth-child(even) { background: #f8fafc; }\n    tbody tr:hover { background: #ccfbf1; }\n    td:last-child, th:last-child { text-align: right; }\n  </style>\n</head>\n<body>\n  <table>\n    <thead><tr><th>Ad</th><th>Fənn</th><th>Bal</th></tr></thead>\n    <tbody>\n      <tr><td>Aysel</td><td>Riyaziyyat</td><td>95</td></tr>\n      <tr><td>Elvin</td><td>Fizika</td><td>82</td></tr>\n      <tr><td>Nigar</td><td>Kimya</td><td>90</td></tr>\n      <tr><td>Murad</td><td>Tarix</td><td>76</td></tr>\n    </tbody>\n  </table>\n</body>\n</html>\n"},
  {"id": "css-17-1", "lang": "css", "level": 17, "title": "Açılan menyu (dropdown)", "keywords": ["dropdown", "açılan menyu", "hover menyu", "выпадающее меню", "submenu", "alt menyu", "css menyu", "menyu açılır"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Açılan menyu (dropdown)</title>\n  <style>\n    body { font-family: Arial, sans-serif; margin: 0; background: #f1f5f9; min-height: 100vh; }\n    .menyu { display: flex; background: #0b1b33; }\n    .menyu a { color: #e2e8f0; text-decoration: none; padding: 14px 20px; display: block; }\n    .menyu a:hover { background: #12294d; color: #5eead4; }\n    .acilan { position: relative; }\n    .icerik { position: absolute; top: 100%; left: 0; min-width: 170px; background: #12294d; border-radius: 0 0 10px 10px; opacity: 0; visibility: hidden; transform: translateY(8px); transition: .2s; }\n    .acilan:hover .icerik, .acilan:focus-within .icerik { opacity: 1; visibility: visible; transform: none; }\n  </style>\n</head>\n<body>\n  <nav class=\"menyu\">\n    <a href=\"#\">Ana səhifə</a>\n    <div class=\"acilan\">\n      <a href=\"#\" class=\"baslat\">Tətbiqlər ▾</a>\n      <div class=\"icerik\"><a href=\"#\">Nibras Arabic</a><a href=\"#\">Nibras PDF</a><a href=\"#\">Nibras Plans</a></div>\n    </div>\n    <a href=\"#\">Əlaqə</a>\n  </nav>\n</body>\n</html>\n"},
  {"id": "css-17-2", "lang": "css", "level": 17, "title": "Tooltip (məlumat qutusu)", "keywords": ["tooltip", "ipucu", "hover məlumat", "подсказка", "data-tip", "məlumat qutusu", "kiçik izah", "attr()"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Tooltip (məlumat qutusu)</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 70px 30px; }\n    .not { color: #64748b; }\n    button { position: relative; padding: 10px 20px; border: 0; border-radius: 8px; background: #0f766e; color: white; font-size: 15px; margin-right: 14px; cursor: pointer; }\n    button::after { content: attr(data-tip); position: absolute; bottom: calc(100% + 10px); left: 50%; transform: translateX(-50%); white-space: nowrap;\n      background: #0f172a; color: #fff; padding: 6px 10px; border-radius: 6px; font-size: 13px; opacity: 0; pointer-events: none; transition: opacity .2s; }\n    button::before { content: \"\"; position: absolute; bottom: calc(100% + 4px); left: 50%; transform: translateX(-50%); border: 6px solid transparent; border-top-color: #0f172a; opacity: 0; transition: opacity .2s; }\n    button:hover::after, button:hover::before { opacity: 1; }\n    .alt { background: #dc2626; }\n  </style>\n</head>\n<body>\n  <p class=\"not\">Düymələrin üzərinə gəlin:</p>\n  <button data-tip=\"Faylı yadda saxla\">Saxla</button>\n  <button data-tip=\"Seçilmiş sətri sil\" class=\"alt\">Sil</button>\n</body>\n</html>\n"},
  {"id": "css-17-3", "lang": "css", "level": 17, "title": "JavaScript-siz tablar", "keywords": ["css tabs", "tab menyu", "radio tabs", "вкладки css", "javascript olmadan", "input radio hack", "tablar", "sekmeler"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>JavaScript-siz tablar</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 24px; background: #f1f5f9; }\n    .tablar { max-width: 420px; background: white; border-radius: 14px; overflow: hidden; box-shadow: 0 6px 18px rgba(0, 0, 0, .1); display: flex; flex-wrap: wrap; }\n    .tablar input { display: none; }\n    .tablar label { flex: 1; text-align: center; padding: 12px; cursor: pointer; background: #e2e8f0; font-weight: bold; color: #475569; }\n    .p { display: none; width: 100%; padding: 20px; order: 5; }\n    #t1:checked ~ .p1, #t2:checked ~ .p2, #t3:checked ~ .p3 { display: block; }\n    #t1:checked + label, #t2:checked + label, #t3:checked + label { background: #0f766e; color: white; }\n  </style>\n</head>\n<body>\n  <div class=\"tablar\">\n    <input type=\"radio\" name=\"t\" id=\"t1\" checked><label for=\"t1\">HTML</label>\n    <input type=\"radio\" name=\"t\" id=\"t2\"><label for=\"t2\">CSS</label>\n    <input type=\"radio\" name=\"t\" id=\"t3\"><label for=\"t3\">JavaScript</label>\n    <div class=\"p p1\">HTML səhifənin skeletini qurur.</div>\n    <div class=\"p p2\">CSS səhifəni bəzəyir və düzür.</div>\n    <div class=\"p p3\">JavaScript səhifəyə davranış verir.</div>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-17-4", "lang": "css", "level": 17, "title": "Çörək qırıntısı və səhifələmə", "keywords": ["breadcrumb", "pagination", "səhifələmə", "naviqasiya yolu", "хлебные крошки", "səhifə nömrələri", "yol göstərici", "::before separator"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Çörək qırıntısı və səhifələmə</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 24px; }\n    .yol { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 24px; font-size: 14px; }\n    .yol a { color: #0f766e; text-decoration: none; }\n    .yol a::after { content: \"/\"; margin-left: 8px; color: #94a3b8; }\n    .yol span { color: #64748b; }\n    .sehife { display: flex; gap: 6px; }\n    .sehife a { min-width: 38px; height: 38px; display: grid; place-items: center; border: 1px solid #cbd5e1; border-radius: 10px; color: #334155; text-decoration: none; }\n    .sehife a:hover { background: #ccfbf1; }\n    .sehife .cari { background: #0f766e; border-color: #0f766e; color: white; }\n  </style>\n</head>\n<body>\n  <nav class=\"yol\"><a href=\"#\">Ana</a><a href=\"#\">Kurslar</a><a href=\"#\">CSS</a><span>Flexbox</span></nav>\n  <div class=\"sehife\">\n    <a href=\"#\">‹</a><a href=\"#\">1</a><a class=\"cari\" href=\"#\">2</a><a href=\"#\">3</a><a href=\"#\">4</a><a href=\"#\">›</a>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-17-5", "lang": "css", "level": 17, "title": "Toggle düymə (açar)", "keywords": ["toggle switch", "açar düyməsi", "checkbox switch", "переключатель", "on off", "aç bağla", "işıq açarı", "ios switch", "checkbox gizlət"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Toggle düymə (açar)</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 30px; display: grid; gap: 18px; }\n    .acar { display: flex; align-items: center; gap: 12px; cursor: pointer; }\n    .acar input { position: absolute; opacity: 0; }\n    .slayd { position: relative; width: 52px; height: 30px; background: #cbd5e1; border-radius: 999px; transition: background .25s; }\n    .slayd::after { content: \"\"; position: absolute; top: 3px; left: 3px; width: 24px; height: 24px; background: white; border-radius: 50%; box-shadow: 0 2px 4px rgba(0, 0, 0, .3); transition: transform .25s; }\n    .acar input:checked + .slayd { background: #14b8a6; }\n    .acar input:checked + .slayd::after { transform: translateX(22px); }\n    .acar input:focus-visible + .slayd { outline: 3px solid #99f6e4; }\n    .acar input:disabled + .slayd { opacity: .5; }\n  </style>\n</head>\n<body>\n  <label class=\"acar\"><input type=\"checkbox\" checked><span class=\"slayd\"></span><b>Bildirişlər</b></label>\n  <label class=\"acar\"><input type=\"checkbox\"><span class=\"slayd\"></span><b>Tünd rejim</b></label>\n  <label class=\"acar\"><input type=\"checkbox\" disabled><span class=\"slayd\"></span><b>Passiv</b></label>\n</body>\n</html>\n"},
  {"id": "css-18-1", "lang": "css", "level": 18, "title": "Fırlanan yükləmə göstəricisi", "keywords": ["spinner", "loader", "yükləmə", "loading", "индикатор загрузки", "fırlanan dairə", "ring spinner", "dual ring", "border spinner"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Fırlanan yükləmə göstəricisi</title>\n  <style>\n    body { margin: 0; min-height: 100vh; display: grid; place-content: center; justify-items: center; gap: 20px; background: #0b1b33; color: #94a3b8; font-family: Arial, sans-serif; }\n    .s { display: flex; gap: 40px; }\n    .halqa { width: 48px; height: 48px; border: 5px solid #1e3a66; border-top-color: #2dd4bf; border-radius: 50%; animation: don .9s linear infinite; }\n    .cift { width: 48px; height: 48px; border-radius: 50%; border: 5px solid transparent; border-top-color: #38bdf8; border-bottom-color: #f59e0b; animation: don 1.2s linear infinite; }\n    .nox { width: 48px; height: 48px; border-radius: 50%; background: conic-gradient(from 0deg, transparent 10%, #a78bfa);\n      -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 6px), #000 calc(100% - 5px));\n      mask: radial-gradient(farthest-side, transparent calc(100% - 6px), #000 calc(100% - 5px)); animation: don 1s linear infinite; }\n    @keyframes don { to { transform: rotate(360deg); } }\n  </style>\n</head>\n<body>\n  <div class=\"s\"><div class=\"halqa\"></div><div class=\"cift\"></div><div class=\"nox\"></div></div>\n  <p>Yüklənir...</p>\n</body>\n</html>\n"},
  {"id": "css-18-2", "lang": "css", "level": 18, "title": "Proqres zolağı", "keywords": ["progress bar", "irəliləyiş zolağı", "proqres", "полоса прогресса", "progress", "faiz zolağı", "yüklənmə faizi", "progress element"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Proqres zolağı</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 30px; max-width: 420px; display: grid; gap: 20px; }\n    .p { background: #e2e8f0; height: 22px; border-radius: 999px; overflow: hidden; }\n    .dol { width: var(--faiz); height: 100%; background: linear-gradient(90deg, #14b8a6, #2563eb); border-radius: 999px; color: white; font-size: 12px; font-weight: bold; display: flex; align-items: center; justify-content: flex-end; padding-right: 8px; box-sizing: border-box; animation: dol 1.4s ease-out; }\n    .zolaq { background: repeating-linear-gradient(45deg, #f59e0b 0 10px, #fbbf24 10px 20px); background-size: 28px 28px; animation: dol 1.4s ease-out, hereket 1s linear infinite; }\n    @keyframes dol { from { width: 0; } }\n    @keyframes hereket { to { background-position: 28px 0; } }\n    progress { width: 100%; height: 14px; accent-color: #0f766e; }\n  </style>\n</head>\n<body>\n  <div class=\"p\"><div class=\"dol\" style=\"--faiz: 70%\"><span>70%</span></div></div>\n  <div class=\"p\"><div class=\"dol zolaq\" style=\"--faiz: 45%\"><span>45%</span></div></div>\n  <progress value=\"60\" max=\"100\"></progress>\n</body>\n</html>\n"},
  {"id": "css-18-3", "lang": "css", "level": 18, "title": "Skeleton yüklənmə", "keywords": ["skeleton loading", "skelet yüklənmə", "placeholder yükləmə", "скелетон", "shimmer", "parıltı effekti", "yüklənən kart", "content loader"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Skeleton yüklənmə</title>\n  <style>\n    body { background: #f1f5f9; display: grid; place-items: center; min-height: 100vh; margin: 0; }\n    .kart { width: 280px; background: white; padding: 16px; border-radius: 16px; display: grid; gap: 12px; }\n    .sk { border-radius: 8px; background: linear-gradient(90deg, #e2e8f0 25%, #f8fafc 50%, #e2e8f0 75%); background-size: 200% 100%; animation: parilti 1.4s infinite linear; }\n    .foto { height: 120px; } .setir { height: 14px; } .uzun { width: 90%; } .qisa { width: 50%; }\n    @keyframes parilti { to { background-position: -200% 0; } }\n  </style>\n</head>\n<body>\n  <div class=\"kart\">\n    <div class=\"sk foto\"></div>\n    <div class=\"sk setir uzun\"></div>\n    <div class=\"sk setir\"></div>\n    <div class=\"sk setir qisa\"></div>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-18-4", "lang": "css", "level": 18, "title": "Nöqtəli yükləmə animasiyası", "keywords": ["dots loader", "üç nöqtə", "typing indicator", "yazır göstəricisi", "точки загрузки", "bouncing dots", "wave loader", "bar loader"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Nöqtəli yükləmə animasiyası</title>\n  <style>\n    body { margin: 0; min-height: 100vh; display: grid; place-content: center; gap: 40px; justify-items: center; background: #0b1b33; }\n    .dots { display: flex; gap: 8px; }\n    .dots i { width: 14px; height: 14px; border-radius: 50%; background: #2dd4bf; animation: sicra 1s ease-in-out infinite; }\n    .dots i:nth-child(2) { animation-delay: .15s; } .dots i:nth-child(3) { animation-delay: .3s; }\n    @keyframes sicra { 0%, 80%, 100% { transform: translateY(0); opacity: .5; } 40% { transform: translateY(-14px); opacity: 1; } }\n    .barlar { display: flex; align-items: center; gap: 5px; height: 50px; }\n    .barlar i { width: 8px; height: 100%; background: #38bdf8; border-radius: 4px; animation: dalga 1s ease-in-out infinite; }\n    .barlar i:nth-child(2) { animation-delay: .1s; } .barlar i:nth-child(3) { animation-delay: .2s; }\n    .barlar i:nth-child(4) { animation-delay: .3s; } .barlar i:nth-child(5) { animation-delay: .4s; }\n    @keyframes dalga { 0%, 100% { transform: scaleY(.3); } 50% { transform: scaleY(1); } }\n  </style>\n</head>\n<body>\n  <div class=\"dots\"><i></i><i></i><i></i></div>\n  <div class=\"barlar\"><i></i><i></i><i></i><i></i><i></i></div>\n</body>\n</html>\n"},
  {"id": "css-18-5", "lang": "css", "level": 18, "title": "Ulduz reytinqi (yalnız CSS)", "keywords": ["star rating", "ulduz reytinqi", "qiymətləndirmə", "рейтинг звезды", "radio ulduz", "direction rtl", "sibling selector", "5 ulduz"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Ulduz reytinqi (yalnız CSS)</title>\n  <style>\n    body { font-family: Arial, sans-serif; text-align: center; padding: 40px; background: #0b1b33; color: #94a3b8; }\n    .reyting { display: inline-flex; flex-direction: row-reverse; gap: 4px; }   /* tərs sıra, ~ seçicisi üçün */\n    .reyting input { display: none; }\n    .reyting label { font-size: 44px; color: #334155; cursor: pointer; transition: color .15s, transform .15s; }\n    .reyting label:hover, .reyting label:hover ~ label, .reyting input:checked ~ label { color: #fbbf24; }\n    .reyting label:hover { transform: scale(1.15); }\n  </style>\n</head>\n<body>\n  <div class=\"reyting\">\n    <input type=\"radio\" name=\"r\" id=\"r5\"><label for=\"r5\">★</label>\n    <input type=\"radio\" name=\"r\" id=\"r4\"><label for=\"r4\">★</label>\n    <input type=\"radio\" name=\"r\" id=\"r3\" checked><label for=\"r3\">★</label>\n    <input type=\"radio\" name=\"r\" id=\"r2\"><label for=\"r2\">★</label>\n    <input type=\"radio\" name=\"r\" id=\"r1\"><label for=\"r1\">★</label>\n  </div>\n  <p>Ulduzlara klikləyin.</p>\n</body>\n</html>\n"},
  {"id": "css-19-1", "lang": "css", "level": 19, "title": "clip-path ilə formalar", "keywords": ["clip-path", "polygon", "forma", "üçbucaq", "altıbucaq", "обрезка по контуру", "hexagon", "ulduz forması", "şəkil kəsmək"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>clip-path ilə formalar</title>\n  <style>\n    body { margin: 0; padding: 24px; background: #0b1b33; font-family: Arial, sans-serif; }\n    .s { display: flex; flex-wrap: wrap; gap: 20px; }\n    .f { width: 120px; height: 120px; display: grid; place-items: center; background: linear-gradient(135deg, #14b8a6, #2563eb); color: white; font-size: 13px; font-weight: bold; }\n    .ucbucaq { clip-path: polygon(50% 0, 100% 100%, 0 100%); padding-top: 40px; box-sizing: border-box; }\n    .altibucaq { clip-path: polygon(25% 5%, 75% 5%, 100% 50%, 75% 95%, 25% 95%, 0 50%); }\n    .ulduz { clip-path: polygon(50% 0, 61% 35%, 98% 35%, 68% 57%, 79% 91%, 50% 70%, 21% 91%, 32% 57%, 2% 35%, 39% 35%); }\n    .daire { clip-path: circle(50%); }\n    .ox { clip-path: polygon(0 30%, 60% 30%, 60% 10%, 100% 50%, 60% 90%, 60% 70%, 0 70%); }\n  </style>\n</head>\n<body>\n  <div class=\"s\">\n    <div class=\"f ucbucaq\">Üçbucaq</div>\n    <div class=\"f altibucaq\">Altıbucaq</div>\n    <div class=\"f ulduz\">Ulduz</div>\n    <div class=\"f daire\">Dairə</div>\n    <div class=\"f ox\">Ox</div>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-19-2", "lang": "css", "level": 19, "title": "Şüşə effekti (backdrop-filter)", "keywords": ["glassmorphism", "şüşə effekti", "backdrop-filter", "blur", "стеклянный эффект", "bulanıq fon", "filter", "buzlu şüşə", "glass card"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Şüşə effekti (backdrop-filter)</title>\n  <style>\n    body { margin: 0; font-family: Arial, sans-serif; }\n    .sehne { position: relative; min-height: 100vh; display: grid; place-items: center; overflow: hidden; background: linear-gradient(135deg, #0f172a, #0f766e); }\n    .top { position: absolute; border-radius: 50%; filter: blur(2px); }\n    .t1 { width: 220px; height: 220px; background: #f59e0b; top: 12%; left: 14%; }\n    .t2 { width: 260px; height: 260px; background: #6366f1; bottom: 8%; right: 12%; }\n    .sise { position: relative; padding: 28px 36px; border-radius: 20px; color: white; text-align: center;\n      background: rgba(255, 255, 255, .14); backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px); border: 1px solid rgba(255, 255, 255, .3); box-shadow: 0 20px 40px rgba(0, 0, 0, .25); }\n    .sise h2 { margin: 0 0 6px; } .sise p { margin: 0; opacity: .9; }\n  </style>\n</head>\n<body>\n  <div class=\"sehne\">\n    <div class=\"top t1\"></div><div class=\"top t2\"></div>\n    <div class=\"sise\"><h2>Şüşə kart</h2><p>Arxa fon bulanıq görünür.</p></div>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-19-3", "lang": "css", "level": 19, "title": "aspect-ratio və scroll-snap", "keywords": ["aspect-ratio", "scroll-snap", "karusel", "slayder", "прокрутка карусель", "en-boy nisbəti", "16/9", "üfüqi sürüşdürmə", "scroll snap karusel"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>aspect-ratio və scroll-snap</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 20px; background: #f1f5f9; }\n    .karusel { display: flex; gap: 12px; overflow-x: auto; scroll-snap-type: x mandatory; padding-bottom: 10px; }\n    .s { flex: 0 0 80%; aspect-ratio: 16 / 9; scroll-snap-align: center; border-radius: 16px; display: grid; place-items: center; font-size: 48px; font-weight: bold; color: white; }\n    .a { background: #0f766e; } .b { background: #2563eb; } .c { background: #7c3aed; } .d { background: #db2777; }\n    .video { width: min(100%, 320px); aspect-ratio: 16 / 9; margin-top: 20px; background: #0f172a; color: #5eead4; display: grid; place-items: center; border-radius: 12px; font-weight: bold; }\n  </style>\n</head>\n<body>\n  <div class=\"karusel\">\n    <div class=\"s a\">1</div><div class=\"s b\">2</div><div class=\"s c\">3</div><div class=\"s d\">4</div>\n  </div>\n  <div class=\"video\">16 / 9</div>\n</body>\n</html>\n"},
  {"id": "css-19-4", "lang": "css", "level": 19, "title": "Hamar sürüşmə və sticky başlıq", "keywords": ["scroll-behavior", "smooth scroll", "sticky header", "yumşaq sürüşmə", "плавная прокрутка", "anchor link", "bölmələrə keçid", "scroll-margin-top"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Hamar sürüşmə və sticky başlıq</title>\n  <style>\n    html { scroll-behavior: smooth; }\n    body { margin: 0; font-family: Arial, sans-serif; }\n    header { position: sticky; top: 0; display: flex; gap: 20px; justify-content: center; padding: 14px; background: #0b1b33; z-index: 5; }\n    header a { color: #5eead4; text-decoration: none; font-weight: bold; }\n    section { min-height: 80vh; display: grid; place-items: center; color: white; scroll-margin-top: 50px; }\n    .b1 { background: #0f766e; } .b2 { background: #2563eb; } .b3 { background: #7c3aed; }\n  </style>\n</head>\n<body>\n  <header><a href=\"#bir\">Bir</a><a href=\"#iki\">İki</a><a href=\"#uc\">Üç</a></header>\n  <section id=\"bir\" class=\"b1\"><h2>Bölmə 1</h2></section>\n  <section id=\"iki\" class=\"b2\"><h2>Bölmə 2</h2></section>\n  <section id=\"uc\" class=\"b3\"><h2>Bölmə 3</h2></section>\n</body>\n</html>\n"},
  {"id": "css-19-5", "lang": "css", "level": 19, "title": "CSS ilə ev və gün şəkli", "keywords": ["css art", "css şəkil", "ev çəkmək", "drawing with css", "рисунок на css", "günəş və ev", "sadə illüstrasiya", "pure css", "dəniz mənzərəsi"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>CSS ilə ev və gün şəkli</title>\n  <style>\n    body { margin: 0; }\n    .sehne { position: relative; width: 100%; height: 100vh; overflow: hidden; background: linear-gradient(#7dd3fc, #e0f2fe); }\n    .gunes { position: absolute; top: 40px; right: 70px; width: 80px; height: 80px; border-radius: 50%; background: #fbbf24; box-shadow: 0 0 0 14px rgba(251, 191, 36, .3); }\n    .bulud { position: absolute; top: 70px; left: 14%; width: 110px; height: 36px; background: white; border-radius: 30px; box-shadow: 30px -14px 0 4px white, 64px 4px 0 -2px white; }\n    .yer { position: absolute; bottom: 0; left: 0; right: 0; height: 28%; background: #4ade80; }\n    .ev { position: absolute; left: 50%; bottom: 28%; transform: translateX(-50%); width: 200px; }\n    .dam { width: 0; height: 0; border-left: 120px solid transparent; border-right: 120px solid transparent; border-bottom: 80px solid #b91c1c; margin-left: -20px; }\n    .divar { position: relative; height: 120px; background: #fde68a; }\n    .qapi { position: absolute; left: 20px; bottom: 0; width: 44px; height: 74px; background: #92400e; border-radius: 6px 6px 0 0; }\n    .pencere { position: absolute; right: 24px; top: 24px; width: 54px; height: 54px; background: #bae6fd; border: 5px solid #92400e; box-sizing: border-box; }\n  </style>\n</head>\n<body>\n  <div class=\"sehne\">\n    <div class=\"gunes\"></div>\n    <div class=\"bulud\"></div>\n    <div class=\"ev\">\n      <div class=\"dam\"></div><div class=\"divar\"><div class=\"qapi\"></div><div class=\"pencere\"></div></div>\n    </div>\n    <div class=\"yer\"></div>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-20-1", "lang": "css", "level": 20, "title": "Landing səhifəsi", "keywords": ["landing page", "açılış səhifəsi", "hero", "sayt şablonu", "лендинг", "giriş səhifəsi", "hero bölməsi", "tətbiq tanıtımı", "ana səhifə dizaynı"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Landing səhifəsi</title>\n  <style>\n    * { box-sizing: border-box; }\n    body { margin: 0; font-family: Arial, sans-serif; color: #0f172a; }\n    .bas { display: flex; justify-content: space-between; align-items: center; padding: 16px 28px; background: #0b1b33; color: #5eead4; }\n    .bas nav { display: flex; gap: 18px; align-items: center; } .bas a { color: #cbd5e1; text-decoration: none; }\n    .bas a.d { background: #14b8a6; color: #042f2e; padding: 8px 16px; border-radius: 10px; font-weight: bold; }\n    .hero { padding: 80px 24px; text-align: center; color: white; background: radial-gradient(circle at 50% 0, #0f766e, #0b1b33 70%); }\n    .hero h1 { font-size: clamp(2rem, 6vw, 3.4rem); margin: 0 0 12px; }\n    .hero p { max-width: 520px; margin: 0 auto 26px; color: #cbd5e1; line-height: 1.6; }\n    .dugme { display: inline-block; background: #5eead4; color: #042f2e; padding: 14px 30px; border-radius: 12px; font-weight: bold; text-decoration: none; transition: transform .2s; }\n    .dugme:hover { transform: translateY(-3px); }\n    .ozellik { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 20px; padding: 48px 28px; background: #f8fafc; }\n    .ozellik div { background: white; padding: 22px; border-radius: 14px; box-shadow: 0 6px 18px rgba(15, 23, 42, .08); }\n    .ozellik h3 { margin: 0 0 6px; color: #0f766e; } .ozellik p { margin: 0; color: #64748b; }\n    footer { text-align: center; padding: 20px; background: #0b1b33; color: #94a3b8; font-size: 14px; }\n  </style>\n</head>\n<body>\n  <header class=\"bas\"><b>Nibras</b><nav><a href=\"#\">Funksiyalar</a><a href=\"#\">Haqqında</a><a href=\"#\" class=\"d\">Başla</a></nav></header>\n  <section class=\"hero\">\n    <h1>Sadə və faydalı tətbiqlər</h1>\n    <p>Reklamsız, rahat və Azərbaycan dilində. Gündəlik işlərinizi asanlaşdırın.</p>\n    <a class=\"dugme\" href=\"#\">İndi yoxla</a>\n  </section>\n  <section class=\"ozellik\">\n    <div><h3>Sürətli</h3><p>Tez açılır və az yer tutur.</p></div>\n    <div><h3>Sadə</h3><p>Heç bir mürəkkəb ayar yoxdur.</p></div>\n    <div><h3>Pulsuz</h3><p>Əsas funksiyalar həmişə pulsuzdur.</p></div>\n  </section>\n  <footer>© 2026 Nibras Code</footer>\n</body>\n</html>\n"},
  {"id": "css-20-2", "lang": "css", "level": 20, "title": "Profil kartı səhifəsi", "keywords": ["profil kartı", "profile card", "vizit kartı", "portfolio kartı", "карточка профиля", "şəxsi səhifə", "sosial linklər", "avatar", "haqqımda"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Profil kartı səhifəsi</title>\n  <style>\n    body { margin: 0; min-height: 100vh; display: grid; place-items: center; background: linear-gradient(135deg, #0b1b33, #0f766e); font-family: Arial, sans-serif; }\n    .profil { width: 300px; background: white; border-radius: 24px; padding: 30px 24px; text-align: center; box-shadow: 0 24px 60px rgba(0, 0, 0, .35); }\n    .avatar { width: 90px; height: 90px; margin: -76px auto 14px; border-radius: 50%; background: linear-gradient(135deg, #14b8a6, #2563eb); color: white; font-size: 38px; font-weight: bold; display: grid; place-items: center; border: 6px solid white; }\n    h1 { margin: 0; font-size: 22px; } .rol { margin: 4px 0 12px; color: #0f766e; font-weight: bold; }\n    .haqqinda { color: #64748b; font-size: 14px; line-height: 1.5; }\n    .reqemler { display: flex; justify-content: space-around; margin: 18px 0; padding: 14px 0; border-block: 1px solid #e2e8f0; }\n    .reqemler b { display: block; font-size: 20px; } .reqemler span { font-size: 12px; color: #64748b; }\n    .linkler { display: flex; gap: 10px; }\n    .linkler a { flex: 1; padding: 10px; border-radius: 10px; background: #0f766e; color: white; text-decoration: none; font-size: 14px; }\n    .linkler a:last-child { background: #e2e8f0; color: #0f172a; }\n  </style>\n</head>\n<body>\n  <main class=\"profil\">\n    <div class=\"avatar\">M</div>\n    <h1>Mahir Əliyev</h1>\n    <p class=\"rol\">Tətbiq tərtibatçısı</p>\n    <p class=\"haqqinda\">Sadə və faydalı tətbiqlər üzərində çalışır.</p>\n    <div class=\"reqemler\"><div><b>3</b><span>Tətbiq</span></div><div><b>20</b><span>Səviyyə</span></div><div><b>5</b><span>Dil</span></div></div>\n    <div class=\"linkler\"><a href=\"#\">Sayt</a><a href=\"#\">E-poçt</a></div>\n  </main>\n</body>\n</html>\n"},
  {"id": "css-20-3", "lang": "css", "level": 20, "title": "Statistika paneli səhifəsi", "keywords": ["dashboard səhifəsi", "statistika paneli", "admin dashboard", "панель статистики", "bar chart css", "qrafik sütunlar", "kartlar və qrafik", "hesabat paneli"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Statistika paneli səhifəsi</title>\n  <style>\n    body { margin: 0; font-family: Arial, sans-serif; background: #0b1b33; color: #e2e8f0; padding: 24px; }\n    h1 { margin: 0 0 18px; color: #5eead4; font-size: 22px; }\n    .kartlar { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 14px; margin-bottom: 18px; }\n    .k { background: #12294d; padding: 16px; border-radius: 14px; display: grid; gap: 4px; }\n    .k span { color: #94a3b8; font-size: 13px; } .k b { font-size: 26px; }\n    .art { color: #4ade80; } .azal { color: #4ade80; }\n    .qrafik { height: 200px; display: flex; align-items: flex-end; gap: 10px; background: #12294d; border-radius: 14px; padding: 18px 18px 8px; }\n    .sutun { flex: 1; height: var(--h); background: linear-gradient(#5eead4, #0f766e); border-radius: 8px 8px 0 0; position: relative; transition: filter .2s; }\n    .sutun:hover { filter: brightness(1.25); }\n    .sutun i { position: absolute; bottom: -22px; left: 0; right: 0; text-align: center; font-style: normal; font-size: 11px; color: #94a3b8; }\n    .qrafik { padding-bottom: 30px; }\n  </style>\n</head>\n<body>\n  <div class=\"panel\">\n    <h1>Həftəlik hesabat</h1>\n    <div class=\"kartlar\">\n      <div class=\"k\"><span>Ziyarət</span><b>12 480</b><small class=\"art\">▲ 12%</small></div>\n      <div class=\"k\"><span>Sorğu</span><b>3 205</b><small class=\"art\">▲ 5%</small></div>\n      <div class=\"k\"><span>Xəta</span><b>14</b><small class=\"azal\">▼ 30%</small></div>\n    </div>\n    <div class=\"qrafik\">\n      <div class=\"sutun\" style=\"--h:55%\"><i>B.e</i></div><div class=\"sutun\" style=\"--h:70%\"><i>Ç.a</i></div>\n      <div class=\"sutun\" style=\"--h:45%\"><i>Çər</i></div><div class=\"sutun\" style=\"--h:90%\"><i>C.a</i></div>\n      <div class=\"sutun\" style=\"--h:65%\"><i>Cüm</i></div><div class=\"sutun\" style=\"--h:35%\"><i>Şən</i></div><div class=\"sutun\" style=\"--h:50%\"><i>Baz</i></div>\n    </div>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-20-4", "lang": "css", "level": 20, "title": "Modal pəncərə (yalnız CSS)", "keywords": ["modal", "popup", "dialog", "pəncərə", "всплывающее окно", ":target modal", "javascript olmadan modal", "overlay", "açılıb bağlanan pəncərə"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Modal pəncərə (yalnız CSS)</title>\n  <style>\n    body { font-family: Arial, sans-serif; padding: 40px; }\n    .ac { background: #0f766e; color: white; padding: 12px 22px; border-radius: 10px; text-decoration: none; }\n    .modal { position: fixed; inset: 0; display: grid; place-items: center; background: rgba(2, 6, 23, .65); opacity: 0; visibility: hidden; transition: .25s; }\n    .modal:target { opacity: 1; visibility: visible; }\n    .fon { position: absolute; inset: 0; }\n    .pencere { position: relative; width: 300px; background: white; padding: 24px; border-radius: 18px; transform: scale(.9); transition: transform .25s; box-shadow: 0 30px 60px rgba(0, 0, 0, .4); }\n    .modal:target .pencere { transform: scale(1); }\n    .pencere h2 { margin: 0 0 8px; } .pencere p { color: #64748b; margin: 0 0 18px; }\n    .d { display: flex; gap: 10px; justify-content: flex-end; }\n    .d a { padding: 8px 16px; border-radius: 10px; text-decoration: none; background: #e2e8f0; color: #0f172a; }\n    .d .beli { background: #0f766e; color: white; }\n  </style>\n</head>\n<body>\n  <a class=\"ac\" href=\"#modal\">Pəncərəni aç</a>\n  <div id=\"modal\" class=\"modal\">\n    <a class=\"fon\" href=\"#\"></a>\n    <div class=\"pencere\">\n      <h2>Təsdiq</h2>\n      <p>Bu əməliyyatı davam etdirmək istəyirsiniz?</p>\n      <div class=\"d\"><a href=\"#\">Ləğv et</a><a class=\"beli\" href=\"#\">Davam et</a></div>\n    </div>\n  </div>\n</body>\n</html>\n"},
  {"id": "css-20-5", "lang": "css", "level": 20, "title": "Akkordeon (FAQ)", "keywords": ["accordion", "akkordeon", "tez-tez verilən suallar", "faq", "аккордеон", "details summary", "açılıb bağlanan bölmə", "sual cavab"], "code": "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Akkordeon (FAQ)</title>\n  <style>\n    body { margin: 0; min-height: 100vh; background: #f1f5f9; font-family: Arial, sans-serif; padding: 30px 16px; }\n    .faq { max-width: 480px; margin: auto; }\n    h1 { color: #0f766e; font-size: 24px; margin-top: 0; }\n    details { background: white; border-radius: 12px; margin-bottom: 10px; box-shadow: 0 3px 10px rgba(0, 0, 0, .06); overflow: hidden; }\n    summary { padding: 16px 18px; cursor: pointer; font-weight: bold; list-style: none; display: flex; justify-content: space-between; align-items: center; }\n    summary::-webkit-details-marker { display: none; }\n    summary::after { content: \"+\"; font-size: 22px; color: #0f766e; transition: transform .2s; }\n    details[open] summary::after { transform: rotate(45deg); }\n    details[open] summary { color: #0f766e; }\n    details p { margin: 0; padding: 0 18px 16px; color: #64748b; line-height: 1.6; }\n  </style>\n</head>\n<body>\n  <main class=\"faq\">\n    <h1>Tez-tez verilən suallar</h1>\n    <details open><summary>Tətbiqlər pulsuzdurmu?</summary><p>Əsas funksiyalar həmişə pulsuzdur və reklam yoxdur.</p></details>\n    <details><summary>Hansı dillər dəstəklənir?</summary><p>Azərbaycan, türk, ingilis, rus və ərəb dilləri.</p></details>\n    <details><summary>Necə əlaqə saxlayım?</summary><p>nibrascode@gmail.com ünvanına yaza bilərsiniz.</p></details>\n  </main>\n</body>\n</html>\n"},
];
